    def test_registered_live_ipc_root_nonempty_recovery_is_replayable(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory() as temporary_directory:
            fixture_root = Path(temporary_directory).resolve(strict=True)
            registry_root = fixture_root / "registry"
            entries = registry_root / "entries"
            entries.mkdir(parents=True, mode=0o700)
            controller = registry_root / "controller.py"
            controller.write_text("pass\n", encoding="utf-8")
            physical_parent = fixture_root / "opt"
            physical_parent.mkdir(mode=0o755)
            parent_metadata = physical_parent.lstat()
            parent_binding = {
                "path": str(physical_parent),
                "device": parent_metadata.st_dev,
                "inode": parent_metadata.st_ino,
                "uid": parent_metadata.st_uid,
                "gid": parent_metadata.st_gid,
                "mode": stat.S_IMODE(parent_metadata.st_mode),
                "host_mount_id": 23,
            }
            target_uid = 60037
            token = "3" * 32
            session_id = "4" * 32
            name = "required-ci-host-ipc-" + session_id
            entries_metadata = entries.lstat()
            registry_binding = {
                "path": str(entries),
                "device": entries_metadata.st_dev,
                "inode": entries_metadata.st_ino,
                "uid": entries_metadata.st_uid,
                "gid": entries_metadata.st_gid,
                "mode": stat.S_IMODE(entries_metadata.st_mode),
            }
            direct_binding = {
                "registry": registry_binding,
                "parent": parent_binding,
                "name": name,
                "target_gid": target_uid,
                "mode": 0o710,
                "root": None,
                "witness": _direct_opt_witness_fixture(session_id),
            }
            session = {
                "root": registry_root,
                "entries": entries,
                "controller_path": controller,
                "token": token,
                "target_uid": target_uid,
                "closed": False,
                "inherited": True,
                "watchdog_authorized": True,
            }
            previous_session = _CANDIDATE_SUPPORT._STRICT_SESSION
            _CANDIDATE_SUPPORT._STRICT_SESSION = session
            opened_parent_generations: list[tuple[int, int, int | None]] = []
            live_parent_generations: dict[int, int] = {}
            parent_proof_descriptors: dict[int, tuple[int, int]] = {}
            parent_generation = 0
            track_parent_ofds = False
            original_close = os.close
            original_dup = os.dup

            def open_parent(expected: object = None):
                nonlocal parent_generation
                self.assertEqual(expected, parent_binding)
                descriptor = os.open(
                    physical_parent,
                    os.O_RDONLY
                    | os.O_DIRECTORY
                    | os.O_NOFOLLOW
                    | os.O_CLOEXEC,
                )
                parent_generation += 1
                proof_descriptor = None
                if track_parent_ofds:
                    proof_descriptor = original_dup(descriptor)
                    parent_proof_descriptors[descriptor] = (
                        parent_generation,
                        proof_descriptor,
                    )
                opened_parent_generations.append(
                    (parent_generation, descriptor, proof_descriptor)
                )
                live_parent_generations[descriptor] = parent_generation
                return descriptor, dict(parent_binding)

            def close_with_generation(descriptor: int) -> None:
                original_close(descriptor)
                live_parent_generations.pop(descriptor, None)
                proof = parent_proof_descriptors.pop(descriptor, None)
                if proof is not None:
                    original_close(proof[1])

            def descriptors_share_open_file_description(
                descriptor: int, proof_descriptor: int
            ) -> bool:
                descriptor_flags = fcntl.fcntl(descriptor, fcntl.F_GETFL)
                proof_flags = fcntl.fcntl(proof_descriptor, fcntl.F_GETFL)
                if descriptor_flags != proof_flags:
                    return False
                toggled_flags = proof_flags ^ os.O_NONBLOCK
                fcntl.fcntl(proof_descriptor, fcntl.F_SETFL, toggled_flags)
                try:
                    return (
                        fcntl.fcntl(descriptor, fcntl.F_GETFL)
                        == fcntl.fcntl(proof_descriptor, fcntl.F_GETFL)
                        == toggled_flags
                    )
                finally:
                    fcntl.fcntl(proof_descriptor, fcntl.F_SETFL, proof_flags)
                    self.assertEqual(
                        fcntl.fcntl(descriptor, fcntl.F_GETFL),
                        descriptor_flags,
                    )

            original_fstat = os.fstat
            selected = physical_parent / name
            original_directory_policy_binding = (
                _CANDIDATE_SUPPORT._directory_policy_binding
            )

            def privileged_group_binding(
                path: Path,
                descriptor: int,
                *,
                description: str,
            ) -> dict[str, object]:
                binding = original_directory_policy_binding(
                    path, descriptor, description=description
                )
                if path == selected:
                    binding["gid"] = target_uid
                return binding

            def privileged_fchown(
                _descriptor: int, selected_uid: int, selected_gid: int
            ) -> None:
                self.assertIn(
                    (selected_uid, selected_gid),
                    (
                        (0, os.getgid()),
                        (registry_binding["uid"], target_uid),
                        (registry_binding["uid"], registry_binding["gid"]),
                    ),
                )

            def linux_directory_unlink_metadata(descriptor: int):
                observed = original_fstat(descriptor)
                if (
                    sys.platform != "linux"
                    and not selected.exists()
                    and stat.S_ISDIR(observed.st_mode)
                    and (observed.st_dev, observed.st_ino)
                    == (root_binding["device"], root_binding["inode"])
                ):
                    values = list(observed)
                    values[3] = 0
                    return os.stat_result(values)
                return observed

            def run_root_broker(
                command: Sequence[str],
                **_kwargs: object,
            ) -> bytes:
                marker_index = command.index("--isolation-opt-ipc-root")
                operation = command[marker_index + 1]
                selected_entry = Path(command[marker_index + 2])
                selected_document = (
                    _CANDIDATE_SUPPORT._load_chain_registry_entry(
                        selected_entry,
                        expected_token=token,
                        expected_target_uid=target_uid,
                        expected_recovery_controller=controller,
                    )
                )
                receipt = (
                    _CANDIDATE_SUPPORT._root_registered_opt_ipc_witness_operation(
                        operation, selected_document
                    )
                )
                receipt.update(
                    {
                        "schema_version": 1,
                        "kind": "direct-opt-root-v1",
                        "token": token,
                        "session_id": session_id,
                        "delete_nonce": selected_document.get(
                            "execution_root_delete_nonce"
                        ),
                    }
                )
                return (
                    _CANDIDATE_SUPPORT._ROOT_TREE_RECEIPT_PREFIX
                    + json.dumps(
                        receipt, sort_keys=True, separators=(",", ":")
                    )
                    + "\n"
                ).encode("ascii")

            try:
                with mock.patch.object(
                    _CANDIDATE_SUPPORT,
                    "_STRICT_LIVE_IPC_PARENT",
                    physical_parent,
                ), mock.patch.object(
                    _CANDIDATE_SUPPORT,
                    "_STRICT_LIVE_IPC_WITNESS_OWNER_UID",
                    os.geteuid(),
                ), mock.patch.object(
                    _CANDIDATE_SUPPORT,
                    "_STRICT_LIVE_IPC_WITNESS_OWNER_GID",
                    os.getegid(),
                ), mock.patch.object(
                    _CANDIDATE_SUPPORT,
                    "_open_strict_live_ipc_parent",
                    side_effect=open_parent,
                ), mock.patch.object(
                    _CANDIDATE_SUPPORT,
                    "_strict_descriptor_mount_id",
                    return_value=23,
                ), mock.patch.object(
                    _CANDIDATE_SUPPORT,
                    "_active_strict_session",
                    return_value=session,
                ), mock.patch.object(
                    _CANDIDATE_SUPPORT,
                    "_directory_policy_binding",
                    side_effect=privileged_group_binding,
                ), mock.patch.object(
                    os, "fchown", side_effect=privileged_fchown
                ):
                    entry_path = _CANDIDATE_SUPPORT._register_trusted_root_chain(
                        controller,
                        None,
                        target_uid,
                        execution_root=physical_parent,
                        cleanup_execution_root=True,
                        cleanup_kind="direct-opt-root-v1",
                        direct_opt_root=direct_binding,
                        session_id=session_id,
                    )
                    precrash_document = (
                        _CANDIDATE_SUPPORT._load_chain_registry_entry(
                            entry_path,
                            expected_token=token,
                            expected_target_uid=target_uid,
                            expected_recovery_controller=controller,
                        )
                    )
                    created = (
                        _CANDIDATE_SUPPORT._root_registered_opt_ipc_witness_operation(
                            "create", precrash_document
                        )
                    )
                    root_binding = created["root"]
                    assert isinstance(root_binding, dict)
                    witness_path = Path(
                        str(created["witness"]["file"]["path"])
                    )
                    self.assertIsNone(
                        precrash_document["direct_opt_root"]["root"]
                    )
                    self.assertEqual(
                        precrash_document["execution_root"],
                        {
                            key: parent_binding[key]
                            for key in ("path", "device", "inode")
                        },
                    )
                    root_descriptor = os.open(
                        selected,
                        os.O_RDONLY
                        | os.O_DIRECTORY
                        | os.O_NOFOLLOW
                        | os.O_CLOEXEC,
                    )
                    self.addCleanup(os.close, root_descriptor)
                    residue = selected / "unknown-residue"
                    residue.write_bytes(b"preserve")

                    with mock.patch.object(
                        _CANDIDATE_SUPPORT, "_stable_uid_zero"
                    ), mock.patch.object(
                        _CANDIDATE_SUPPORT,
                        "_run_registered_sudo",
                        side_effect=run_root_broker,
                    ), self.assertRaisesRegex(
                        AssertionError, "not empty"
                    ):
                        _CANDIDATE_SUPPORT._recover_registered_entry(
                            entry_path, allow_recovery_broker=True
                        )

                    retained = _CANDIDATE_SUPPORT._load_chain_registry_entry(
                        entry_path,
                        expected_token=token,
                        expected_target_uid=target_uid,
                        expected_recovery_controller=controller,
                    )
                    retained_nonce = retained["execution_root_delete_nonce"]
                    self.assertEqual(retained["state"], "deleting")
                    self.assertRegex(str(retained_nonce), r"^[0-9a-f]{32}$")
                    self.assertIsNone(retained["direct_opt_root"]["root"])
                    self.assertIsNone(retained["execution_root_deleted"])
                    self.assertEqual(residue.read_bytes(), b"preserve")
                    retained_witness_bytes = witness_path.read_bytes()
                    held_metadata = os.fstat(root_descriptor)
                    self.assertEqual(
                        (held_metadata.st_dev, held_metadata.st_ino),
                        (root_binding["device"], root_binding["inode"]),
                    )

                    with mock.patch.object(
                        _CANDIDATE_SUPPORT, "_stable_uid_zero"
                    ), mock.patch.object(
                        _CANDIDATE_SUPPORT,
                        "_run_registered_sudo",
                        side_effect=run_root_broker,
                    ), self.assertRaisesRegex(
                        AssertionError, "not empty"
                    ):
                        _CANDIDATE_SUPPORT._recover_registered_entry(
                            entry_path, allow_recovery_broker=True
                        )
                    replayed = _CANDIDATE_SUPPORT._load_chain_registry_entry(
                        entry_path,
                        expected_token=token,
                        expected_target_uid=target_uid,
                        expected_recovery_controller=controller,
                    )
                    self.assertEqual(
                        replayed["execution_root_delete_nonce"], retained_nonce
                    )
                    self.assertIsNone(replayed["direct_opt_root"]["root"])
                    self.assertEqual(
                        witness_path.read_bytes(), retained_witness_bytes
                    )

                    residue.unlink()
                    crash_document = (
                        _CANDIDATE_SUPPORT._load_chain_registry_entry(
                            entry_path,
                            expected_token=token,
                            expected_target_uid=target_uid,
                            expected_recovery_controller=controller,
                        )
                    )
                    invocation_entry_path = (
                        entries / ("chain-" + "5" * 32 + ".json")
                    )
                    invocation_bytes = b"{}"
                    invocation_entry_path.write_bytes(invocation_bytes)
                    invocation_entry_path.chmod(0o600)
                    invocation_launcher = (
                        501,
                        502,
                        1,
                        501,
                        501,
                        (registry_binding["uid"],) * 4,
                    )

                    def open_crash_invocation(
                        registry_fd: int,
                        selected_registry: Mapping[str, object],
                        selected_path: Path,
                        runner_uid: int,
                        selected_target_uid: int,
                        selected_token: str,
                    ):
                        self.assertEqual(selected_registry, registry_binding)
                        self.assertEqual(selected_path, invocation_entry_path)
                        self.assertEqual(runner_uid, registry_binding["uid"])
                        self.assertEqual(selected_target_uid, target_uid)
                        self.assertEqual(selected_token, token)
                        descriptor = os.open(
                            invocation_entry_path.name,
                            os.O_RDONLY
                            | os.O_NOFOLLOW
                            | os.O_CLOEXEC,
                            dir_fd=registry_fd,
                        )
                        metadata = os.fstat(descriptor)
                        data = os.pread(descriptor, 4097, 0)
                        return (
                            descriptor,
                            metadata,
                            data,
                            {"fixture": "invocation"},
                            invocation_launcher,
                        )

                    broker_arguments = (
                        "cleanup",
                        str(entry_path),
                        str(invocation_entry_path),
                        json.dumps(
                            registry_binding,
                            sort_keys=True,
                            separators=(",", ":"),
                        ),
                        json.dumps(
                            parent_binding,
                            sort_keys=True,
                            separators=(",", ":"),
                        ),
                        name,
                        str(registry_binding["uid"]),
                        str(target_uid),
                        "-",
                        token,
                        session_id,
                        str(crash_document["execution_root_delete_nonce"]),
                        "-",
                    )
                    marker_read_fd, marker_write_fd = os.pipe()
                    fixture_euid = os.geteuid()
                    child_pid: int | None = None
                    with _CANDIDATE_SUPPORT._chain_registry_lock(entry_path):
                        child_pid = os.fork()
                        if child_pid == 0:
                            track_parent_ofds = True
                            os.close(marker_read_fd)
                            child_parent_open_start = len(
                                opened_parent_generations
                            )
                            live_parent_generations.clear()
                            real_append = (
                                _CANDIDATE_SUPPORT._append_strict_live_ipc_witness_record
                            )
                            real_fsync = os.fsync
                            parent_fsync_observed = False
                            euid_calls = 0

                            def root_then_witness_owner() -> int:
                                nonlocal euid_calls
                                euid_calls += 1
                                return 0 if euid_calls == 1 else fixture_euid

                            def pause_before_deleted_record(
                                *arguments: object, **keywords: object
                            ):
                                if keywords.get("phase") == "deleted":
                                    if not parent_fsync_observed:
                                        os.write(marker_write_fd, b"X")
                                    os.write(marker_write_fd, b"D")
                                    while True:
                                        signal.pause()
                                return real_append(*arguments, **keywords)

                            def observe_parent_fsync(descriptor: int) -> None:
                                nonlocal parent_fsync_observed
                                real_fsync(descriptor)
                                metadata = os.fstat(descriptor)
                                expected_parent_generation = (
                                    opened_parent_generations[
                                        child_parent_open_start + 1
                                    ]
                                    if len(opened_parent_generations)
                                    > child_parent_open_start + 1
                                    else None
                                )
                                if (
                                    not parent_fsync_observed
                                    and expected_parent_generation is not None
                                    and descriptor
                                    == expected_parent_generation[1]
                                    and live_parent_generations.get(descriptor)
                                    == expected_parent_generation[0]
                                    and expected_parent_generation[2] is not None
                                    and descriptors_share_open_file_description(
                                        descriptor,
                                        expected_parent_generation[2],
                                    )
                                    and stat.S_ISDIR(metadata.st_mode)
                                    and (metadata.st_dev, metadata.st_ino)
                                    == (
                                        parent_binding["device"],
                                        parent_binding["inode"],
                                    )
                                ):
                                    try:
                                        os.stat(
                                            name,
                                            dir_fd=descriptor,
                                            follow_symlinks=False,
                                        )
                                    except FileNotFoundError:
                                        parent_fsync_observed = True
                                        os.write(marker_write_fd, b"F")

                            try:
                                p = mock.patch.object
                                with contextlib.ExitStack() as stack:
                                    for manager in (
                                        p(_CANDIDATE_SUPPORT, "_TRUSTED_SUPPORT_PATH", controller),
                                        p(os, "getuid", return_value=0),
                                        p(os, "geteuid", side_effect=root_then_witness_owner),
                                        mock.patch.multiple(
                                            _CANDIDATE_SUPPORT,
                                            _bind_root_controller_parent=mock.DEFAULT,
                                            _root_open_registered_opt_ipc_invocation=mock.Mock(side_effect=open_crash_invocation),
                                            _strict_owner_loss_registered_broker_ancestry=mock.DEFAULT,
                                        ),
                                        p(_CANDIDATE_SUPPORT, "_append_strict_live_ipc_witness_record", side_effect=pause_before_deleted_record),
                                        p(os, "fsync", side_effect=observe_parent_fsync),
                                        p(os, "close", side_effect=close_with_generation),
                                        p(os, "fstat", side_effect=linux_directory_unlink_metadata),
                                    ):
                                        stack.enter_context(manager)
                                    child_result = (
                                        _CANDIDATE_SUPPORT._root_registered_opt_ipc_root_main(
                                            broker_arguments
                                        )
                                    )
                            except BaseException:
                                child_result = 97
                            finally:
                                os.close(marker_write_fd)
                            os._exit(child_result)

                        os.close(marker_write_fd)
                        try:
                            marker_value = bytearray()
                            marker_deadline = time.monotonic() + 10
                            while len(marker_value) < 2:
                                remaining = marker_deadline - time.monotonic()
                                if remaining <= 0:
                                    break
                                readable, _, _ = (
                                    _CANDIDATE_SUPPORT.select.select(
                                        [marker_read_fd], [], [], remaining
                                    )
                                )
                                if not readable:
                                    break
                                chunk = os.read(
                                    marker_read_fd, 2 - len(marker_value)
                                )
                                if not chunk:
                                    break
                                marker_value.extend(chunk)
                            self.assertEqual(bytes(marker_value), b"FD")
                            self.assertFalse(selected.exists())
                            os.kill(child_pid, signal.SIGKILL)
                            waited_pid, child_status = os.waitpid(child_pid, 0)
                            self.assertEqual(waited_pid, child_pid)
                            self.assertTrue(os.WIFSIGNALED(child_status))
                            self.assertEqual(
                                os.WTERMSIG(child_status), signal.SIGKILL
                            )
                            child_pid = None
                        finally:
                            os.close(marker_read_fd)
                            if child_pid is not None:
                                try:
                                    os.kill(child_pid, signal.SIGKILL)
                                except ProcessLookupError:
                                    pass
                                os.waitpid(child_pid, 0)
                    with mock.patch.object(
                        os,
                        "fstat",
                        side_effect=linux_directory_unlink_metadata,
                    ):
                        deleted_link_count = os.fstat(root_descriptor).st_nlink
                    root_persisted = (
                        _CANDIDATE_SUPPORT._load_chain_registry_entry(
                            entry_path,
                            expected_token=token,
                            expected_target_uid=target_uid,
                            expected_recovery_controller=controller,
                        )
                    )
                    self.assertEqual(root_persisted["state"], "deleting")
                    self.assertIsNone(
                        root_persisted["direct_opt_root"]["root"]
                    )
                    self.assertIsNone(
                        root_persisted["execution_root_deleted"]
                    )
                    self.assertFalse(selected.exists())
                    with mock.patch.object(
                        _CANDIDATE_SUPPORT, "_stable_uid_zero"
                    ), mock.patch.object(
                        _CANDIDATE_SUPPORT,
                        "_run_registered_sudo",
                        side_effect=run_root_broker,
                    ), mock.patch.object(
                        os,
                        "fstat",
                        side_effect=linux_directory_unlink_metadata,
                    ):
                        _CANDIDATE_SUPPORT._recover_registered_entry(
                            entry_path, allow_recovery_broker=True
                        )

                    recovered = _CANDIDATE_SUPPORT._load_chain_registry_entry(
                        entry_path,
                        expected_token=token,
                        expected_target_uid=target_uid,
                        expected_recovery_controller=controller,
                    )
            finally:
                _CANDIDATE_SUPPORT._STRICT_SESSION = previous_session

            self.assertEqual(recovered["state"], "closed")
            self.assertEqual(
                recovered["execution_root_delete_nonce"], retained_nonce
            )
            self.assertEqual(recovered["direct_opt_root"]["root"], root_binding)
            self.assertEqual(
                recovered["execution_root_deleted"],
                {
                    "kind": "direct-empty-rmdir-v1",
                    "parent_device": parent_binding["device"],
                    "parent_inode": parent_binding["inode"],
                    "device": root_binding["device"],
                    "inode": root_binding["inode"],
                    "name": name,
                },
            )
            self.assertFalse(selected.exists())
            self.assertEqual(deleted_link_count, 0)


    def _exercise_real_watchdog_owner_sigkill_replays_registered_live_ipc_root(
        self,
    ) -> None:
        if sys.platform != "linux":
            self.skipTest("real registry watchdog recovery requires Linux")
        if (
            os.environ.get(REQUIRED_CI_ISOLATION_MODE_ENV)
            != REQUIRED_CI_ISOLATION_MODE
        ):
            self.skipTest(
                "real registry watchdog recovery requires the trusted strict suite"
            )
        if not hasattr(os, "pidfd_open") or not hasattr(
            signal, "pidfd_send_signal"
        ):
            self.skipTest("real registry watchdog recovery requires pidfds")

        ready_prefix = b"REQUIRED_CI_WATCHDOG_OWNER_READY:"
        owner_source = textwrap.dedent(
            """
            import json
            import os
            from pathlib import Path
            import runpy
            import signal
            import socket
            import sys

            support = runpy.run_path(sys.argv[1])
            registry = support["trusted_isolation_chain_registry"]()
            real_write = support["_write_chain_registry_entry"]

            def pause_before_trusted_import(
                path,
                document,
                *,
                create,
                published_callback=None,
            ):
                direct = document.get("direct_opt_root")
                witness = direct.get("witness") if isinstance(direct, dict) else None
                witness_file = (
                    witness.get("file") if isinstance(witness, dict) else None
                )
                if (
                    create is False
                    and document.get("cleanup_kind") == "direct-opt-root-v1"
                    and document.get("state") == "prepared"
                    and isinstance(direct.get("root"), dict)
                    and isinstance(witness_file, dict)
                    and witness_file.get("phase") == "root-bound"
                ):
                    before = support["_load_chain_registry_entry"](path)
                    if (
                        before["direct_opt_root"]["root"] is not None
                        or before["direct_opt_root"]["witness"]["file"] is not None
                    ):
                        raise AssertionError(
                            "trusted registry imported the root proof too early"
                        )
                    session = support["_active_strict_session"]()
                    watchdog = session["watchdog_process"]
                    heartbeat = session["watchdog_heartbeat"]
                    if not heartbeat.is_alive():
                        raise AssertionError("watchdog heartbeat is not active")
                    root_path = Path(str(direct["root"]["path"]))
                    listener = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
                    socket_path = root_path / "post-seal.sock"
                    fifo_path = root_path / "post-seal.fifo"
                    listener.bind(str(socket_path))
                    socket_path.chmod(0o666)
                    os.mkfifo(fifo_path, 0o666)
                    fifo_path.chmod(0o666)
                    residues = {}
                    for residue_path, kind in (
                        (socket_path, "socket"),
                        (fifo_path, "fifo"),
                    ):
                        metadata = residue_path.lstat()
                        residues[residue_path.name] = {
                            "device": metadata.st_dev,
                            "inode": metadata.st_ino,
                            "uid": metadata.st_uid,
                            "gid": metadata.st_gid,
                            "mode": metadata.st_mode & 0o7777,
                            "nlink": metadata.st_nlink,
                            "size": metadata.st_size,
                            "kind": kind,
                        }
                    marker = {
                        "owner_pid": os.getpid(),
                        "registry_root": str(registry["root"]),
                        "entry_path": str(path),
                        "session_id": document["session_id"],
                        "registry_token": document["token"],
                        "publication_nonce": document["publication_nonce"],
                        "parent": direct["parent"],
                        "root": direct["root"],
                        "residues": residues,
                        "witness": witness,
                        "watchdog_pid": watchdog.pid,
                        "watchdog_stdout_fd": watchdog.stdout.fileno(),
                        "watchdog_token": session["watchdog_token"],
                        "watchdog_identity": [
                            *session["watchdog_identity"][:5],
                            list(session["watchdog_identity"][5]),
                        ],
                    }
                    print(
                        "REQUIRED_CI_WATCHDOG_OWNER_READY:"
                        + json.dumps(
                            marker, sort_keys=True, separators=(",", ":")
                        ),
                        flush=True,
                    )
                    while True:
                        signal.pause()
                return real_write(
                    path,
                    document,
                    create=create,
                    published_callback=published_callback,
                )

            support["_write_chain_registry_entry"] = pause_before_trusted_import
            with support["_registered_live_host_ipc_root"]():
                raise AssertionError(
                    "strict live IPC root reached the target before the crash seam"
                )
            """
        )
        owner_environment = _CANDIDATE_SUPPORT._minimal_supervisor_environment()
        owner_environment[_CANDIDATE_SUPPORT.ISOLATION_MODE_ENV] = (
            _CANDIDATE_SUPPORT.STRICT_ISOLATION_MODE
        )
        captured_support_stack = contextlib.ExitStack()
        staged_support_path = captured_support_stack.enter_context(
            _owner_private_captured_support_path()
        )
        owner = subprocess.Popen(
            [
                str(_CANDIDATE_SUPPORT._STRICT_PRIMITIVES["python"]),
                *_CANDIDATE_SUPPORT._ROOT_PYTHON_ARGUMENTS,
                "-c",
                owner_source,
                str(staged_support_path),
            ],
            cwd=str(TRUSTED_REPO_ROOT),
            env=owner_environment,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            start_new_session=True,
        )
        owner_pidfd: int | None = None
        watchdog_output_fd: int | None = None
        watchdog_pidfd: int | None = None
        marker: dict[str, object] | None = None
        try:
            self.assertIsNotNone(owner.stdout)
            assert owner.stdout is not None
            ready_line = _CANDIDATE_SUPPORT._read_watchdog_line(
                owner.stdout, 45, "real owner readiness"
            )
            self.assertTrue(ready_line.startswith(ready_prefix), ready_line)
            marker = json.loads(ready_line[len(ready_prefix) :])
            self.assertIsInstance(marker, dict)
            assert isinstance(marker, dict)
            self.assertEqual(marker["owner_pid"], owner.pid)
            self.assertRegex(str(marker["session_id"]), r"^[0-9a-f]{32}$")
            self.assertRegex(
                str(marker["registry_token"]), r"^[0-9a-f]{32}$"
            )
            self.assertRegex(
                str(marker["publication_nonce"]), r"^[0-9a-f]{32}$"
            )
            root_binding = marker["root"]
            parent_binding = marker["parent"]
            witness_binding = marker["witness"]
            self.assertIsInstance(root_binding, dict)
            self.assertIsInstance(parent_binding, dict)
            self.assertIsInstance(witness_binding, dict)
            assert isinstance(root_binding, dict)
            assert isinstance(parent_binding, dict)
            assert isinstance(witness_binding, dict)
            root_path = Path(str(root_binding["path"]))
            entry_path = Path(str(marker["entry_path"]))
            registry_root = Path(str(marker["registry_root"]))
            witness_namespace = witness_binding["namespace"]
            witness_file = witness_binding["file"]
            self.assertIsInstance(witness_namespace, dict)
            self.assertIsInstance(witness_file, dict)
            assert isinstance(witness_namespace, dict)
            assert isinstance(witness_file, dict)
            expected_witness_path = _strict_live_broker_witness_path(
                marker,
                witness_binding,
                witness_namespace,
                witness_file,
            )
            self.assertEqual(parent_binding["path"], "/opt")
            self.assertEqual(root_path.parent, Path("/opt"))
            self.assertEqual(
                expected_witness_path.parent,
                Path("/opt/.codex-required-ci-witnesses"),
            )
            self.assertEqual(
                set(witness_namespace),
                {"path", "device", "inode", "uid", "gid", "mode"},
            )
            self.assertEqual(
                (
                    witness_namespace["path"],
                    witness_namespace["device"],
                    witness_namespace["uid"],
                    witness_namespace["gid"],
                    witness_namespace["mode"],
                ),
                (
                    str(expected_witness_path.parent),
                    parent_binding["device"],
                    0,
                    0,
                    0o700,
                ),
            )
            self.assertEqual(
                (
                    witness_file["path"],
                    witness_file["uid"],
                    witness_file["gid"],
                    witness_file["mode"],
                    witness_file["nlink"],
                    witness_file["phase"],
                ),
                (
                    str(expected_witness_path),
                    0,
                    0,
                    0o600,
                    1,
                    "root-bound",
                ),
            )
            self.assertGreater(witness_file["size"], 0)
            self.assertRegex(witness_file["sha256"], r"^[0-9a-f]{64}$")
            self.assertRegex(witness_file["last_record_sha256"], r"^[0-9a-f]{64}$")
            residues = marker["residues"]
            self.assertEqual(
                set(residues), {"post-seal.sock", "post-seal.fifo"}
            )
            for basename, expected_kind in (
                ("post-seal.sock", "socket"),
                ("post-seal.fifo", "fifo"),
            ):
                residue = residues[basename]
                self.assertEqual(residue["kind"], expected_kind)
                self.assertEqual(residue["device"], root_binding["device"])
                self.assertEqual(residue["uid"], os.getuid())
                self.assertEqual(residue["gid"], os.getgid())
                self.assertEqual(residue["mode"], 0o666)
                self.assertEqual(residue["nlink"], 1)
                self.assertEqual(residue["size"], 0)
                self.assertEqual(
                    (root_path / basename).lstat().st_ino,
                    residue["inode"],
                )
            self.assertTrue(root_path.is_dir())
            self.assertTrue(entry_path.is_file())
            with self.assertRaises(PermissionError) as denied_witness:
                expected_witness_path.read_bytes()
            self.assertEqual(denied_witness.exception.errno, errno.EACCES)
            preimport_document = json.loads(entry_path.read_bytes())
            self.assertIsNone(preimport_document["direct_opt_root"]["root"])
            self.assertIsNone(
                preimport_document["direct_opt_root"]["witness"]["file"]
            )
            self.assertEqual(
                preimport_document["publication_nonce"],
                marker["publication_nonce"],
            )

            watchdog_pid = int(marker["watchdog_pid"])
            serialized_watchdog_identity = marker["watchdog_identity"]
            self.assertIsInstance(serialized_watchdog_identity, list)
            assert isinstance(serialized_watchdog_identity, list)
            self.assertEqual(len(serialized_watchdog_identity), 6)
            self.assertIsInstance(serialized_watchdog_identity[5], list)
            watchdog_identity = (
                *serialized_watchdog_identity[:5],
                tuple(serialized_watchdog_identity[5]),
            )
            self.assertEqual(watchdog_identity[0], watchdog_pid)
            watchdog_output_fd = os.open(
                f"/proc/{owner.pid}/fd/{int(marker['watchdog_stdout_fd'])}",
                os.O_RDONLY | os.O_CLOEXEC,
            )
            watchdog_pidfd = os.pidfd_open(watchdog_pid, 0)
            self.assertEqual(entry_path.parent, registry_root / "entries")
            self.assertEqual(
                preimport_document["direct_opt_root"]["registry"]["path"],
                str(entry_path.parent),
            )
            self.assertEqual(
                _CANDIDATE_SUPPORT._watchdog_client_inventory(
                    entry_path.parent,
                    str(marker["registry_token"]),
                    runner_uid=os.getuid(),
                    excluded_identity=watchdog_identity,
                    minimum_start_time=watchdog_identity[1],
                ),
                {},
            )
            owner_pidfd = os.pidfd_open(owner.pid, 0)
            signal.pidfd_send_signal(owner_pidfd, signal.SIGKILL, None, 0)
            owner.wait(timeout=10)
            self.assertEqual(owner.returncode, -signal.SIGKILL)

            with os.fdopen(
                os.dup(watchdog_output_fd), "rb", closefd=True
            ) as watchdog_output:
                result_line = _CANDIDATE_SUPPORT._read_watchdog_line(
                    watchdog_output, 45, "real owner-loss result"
                )
            result_prefix = _CANDIDATE_SUPPORT._WATCHDOG_RESULT_PREFIX.encode(
                "ascii"
            )
            self.assertTrue(result_line.startswith(result_prefix), result_line)
            result = json.loads(result_line[len(result_prefix) :])
            self.assertEqual(result["status"], "complete")
            self.assertEqual(result["token"], marker["watchdog_token"])
            terminal = result["terminal"]
            self.assertEqual(terminal["reason"], "owner-eof")
            self.assertIs(type(terminal["elapsed_ns"]), int)
            self.assertIs(type(terminal["heartbeat_timeout_ns"]), int)
            self.assertLess(
                terminal["elapsed_ns"], terminal["heartbeat_timeout_ns"]
            )
            recovery = result["recovery"]
            self.assertEqual(recovery["direct_opt_root_count"], 1)
            recovered_root = recovery["direct_opt_root"]
            self.assertEqual(
                recovered_root["session_id"], marker["session_id"]
            )
            self.assertEqual(
                recovered_root["token"], marker["registry_token"]
            )
            self.assertRegex(
                recovered_root["delete_nonce"], r"^[0-9a-f]{32}$"
            )
            self.assertEqual(
                (
                    recovered_root["parent_device"],
                    recovered_root["parent_inode"],
                ),
                (parent_binding["device"], parent_binding["inode"]),
            )
            self.assertEqual(
                (
                    recovered_root["root_device"],
                    recovered_root["root_inode"],
                ),
                (root_binding["device"], root_binding["inode"]),
            )
            self.assertEqual(
                recovered_root["deleted"],
                {
                    "kind": "direct-empty-rmdir-v1",
                    "parent_device": parent_binding["device"],
                    "parent_inode": parent_binding["inode"],
                    "device": root_binding["device"],
                    "inode": root_binding["inode"],
                    "name": root_path.name,
                },
            )
            self.assertEqual(
                recovered_root["witness_nonce"], witness_binding["nonce"]
            )
            witness_retired = recovered_root["witness_retired"]
            self.assertIsInstance(witness_retired, dict)
            assert isinstance(witness_retired, dict)
            self.assertEqual(set(witness_retired), {*witness_file, "absent"})
            self.assertIs(witness_retired["absent"], False)
            self.assertEqual(witness_retired["phase"], "deleted")
            _assert_strict_live_terminal_witness_progress(
                witness_file, witness_retired
            )
            self.assertEqual(
                recovered_root["witness_last_record_sha256"],
                witness_retired["last_record_sha256"],
            )
            stable_witness_fields = (
                "path",
                "device",
                "inode",
                "uid",
                "gid",
                "mode",
                "nlink",
            )
            self.assertEqual(
                tuple(witness_retired[field] for field in stable_witness_fields),
                tuple(witness_file[field] for field in stable_witness_fields),
            )
            self.assertFalse(root_path.exists())
            with self.assertRaises(PermissionError) as denied_retired_witness:
                expected_witness_path.read_bytes()
            self.assertEqual(denied_retired_witness.exception.errno, errno.EACCES)
            self.assertFalse(registry_root.exists())

            deadline = time.monotonic() + 10
            while time.monotonic() < deadline:
                observed = _CANDIDATE_SUPPORT._process_identity(
                    Path("/proc") / str(watchdog_pid)
                )
                if (
                    observed is None
                    or tuple(observed[:5]) != watchdog_identity[:5]
                ):
                    break
                time.sleep(0.05)
            else:
                self.fail("real registry watchdog was not reaped")
        finally:
            if owner.poll() is None:
                try:
                    os.kill(owner.pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
                owner.wait(timeout=10)
            if marker is not None and watchdog_pidfd is not None:
                try:
                    signal.pidfd_send_signal(
                        watchdog_pidfd, signal.SIGKILL, None, 0
                    )
                except ProcessLookupError:
                    pass
            for descriptor in (
                owner_pidfd,
                watchdog_pidfd,
                watchdog_output_fd,
            ):
                if descriptor is not None:
                    try:
                        os.close(descriptor)
                    except OSError:
                        pass
            for stream in (owner.stdout, owner.stderr):
                if stream is not None:
                    stream.close()
            captured_support_stack.close()

    def _exercise_strict_systemd_scope_aggregate_limits(
        self, candidate_root: Path, candidate_sha: str
    ) -> None:
        if sys.platform != "linux":
            self.skipTest("strict systemd aggregate probes require Linux")
        self.assertEqual(
            os.environ.get(REQUIRED_CI_ISOLATION_MODE_ENV),
            REQUIRED_CI_ISOLATION_MODE,
        )
        _CANDIDATE_SUPPORT._ensure_strict_backend()
        source_body = textwrap.dedent(
            r'''
            import errno
            import json
            import os
            from pathlib import Path
            import resource
            import signal
            import sys
            import time

            def read(path):
                value = path.read_text(encoding="ascii")
                if not value.endswith("\n") or "\x00" in value or "\r" in value:
                    raise SystemExit(70)
                return value[:-1]

            def counters(path):
                result = {}
                for line in read(path).splitlines():
                    fields = line.split()
                    if len(fields) != 2 or not fields[1].isdigit():
                        raise SystemExit(71)
                    result[fields[0]] = int(fields[1])
                return result

            if len(sys.argv) != 4 or sys.argv[1] not in ("process-cpu", "memory"):
                raise SystemExit(72)
            mode, expected_unit, stop_value = sys.argv[1:]
            membership = read(Path("/proc/self/cgroup"))
            fields = membership.split(":")
            if len(fields) != 3 or fields[:2] != ["0", ""]:
                raise SystemExit(73)
            control_group = fields[2]
            root = Path("/sys/fs/cgroup") / control_group[1:]
            caps = {
                name: read(root / name)
                for name in (
                    "cpu.max", "memory.high", "memory.max",
                    "memory.swap.max", "pids.max",
                )
            }
            if (
                not control_group.startswith("/")
                or root.name != expected_unit
                or read(root / "cgroup.type") != "domain"
                or caps != {
                    "cpu.max": "200000 100000",
                    "memory.high": "805306368",
                    "memory.max": "1073741824",
                    "memory.swap.max": "0",
                    "pids.max": "64",
                }
            ):
                raise SystemExit(74)

            if mode == "process-cpu":
                nproc_soft, nproc_hard = resource.getrlimit(resource.RLIMIT_NPROC)
                before_pids = counters(root / "pids.events").get("max", 0)
                children = []
                limited = False
                try:
                    while len(children) < 128:
                        try:
                            pid = os.fork()
                        except OSError as error:
                            if error.errno != errno.EAGAIN:
                                raise
                            limited = True
                            break
                        if pid == 0:
                            while True:
                                signal.pause()
                        children.append(pid)
                    after_pids = counters(root / "pids.events").get("max", 0)
                finally:
                    for pid in children:
                        try:
                            os.kill(pid, signal.SIGKILL)
                        except ProcessLookupError:
                            pass
                    for pid in children:
                        os.waitpid(pid, 0)
                if not limited:
                    raise SystemExit(75)
                affinity = len(os.sched_getaffinity(0))
                if affinity < 3:
                    raise SystemExit(76)
                before_cpu = counters(root / "cpu.stat").get("nr_throttled", 0)
                workers = []
                for _ in range(min(8, affinity)):
                    pid = os.fork()
                    if pid == 0:
                        deadline = time.monotonic() + 2.0
                        value = 1
                        while time.monotonic() < deadline:
                            value = (value * 1664525 + 1013904223) & 0xffffffff
                        os._exit(0 if value >= 0 else 77)
                    workers.append(pid)
                for pid in workers:
                    waited, status = os.waitpid(pid, 0)
                    if waited != pid or status != 0:
                        raise SystemExit(78)
                document = {
                    "kind": mode,
                    "unit": expected_unit,
                    "control_group": control_group,
                    "caps": caps,
                    "nproc_soft": nproc_soft,
                    "nproc_hard": nproc_hard,
                    "forked": len(children),
                    "pids_max_delta": after_pids - before_pids,
                    "affinity_cpus": affinity,
                    "nr_throttled_delta": (
                        counters(root / "cpu.stat").get("nr_throttled", 0)
                        - before_cpu
                    ),
                }
            else:
                stop = Path(stop_value)
                worker_count = 4
                bytes_per_worker = 205 * 1024 * 1024
                before = counters(root / "memory.events")
                workers = set()
                try:
                    for _ in range(worker_count):
                        pid = os.fork()
                        if pid == 0:
                            blocks = []
                            blocks_required = bytes_per_worker // (256 * 1024)
                            for _ in range(blocks_required):
                                if stop.exists():
                                    os._exit(0)
                                block = bytearray(256 * 1024)
                                for offset in range(0, len(block), 4096):
                                    block[offset] = 1
                                blocks.append(block)
                                time.sleep(0.002)
                            _strict_memory_worker_hold(
                                stop, blocks, time.monotonic, time.sleep, os._exit
                            )
                        workers.add(pid)
                    _strict_memory_high_gate(
                        before.get("high", 0),
                        lambda: counters(root / "memory.events").get("high", 0),
                        lambda: stop.write_text("stop\n", encoding="ascii"),
                        time.monotonic,
                        time.sleep,
                    )
                    for pid in tuple(workers):
                        waited, status = os.waitpid(pid, 0)
                        workers.remove(pid)
                        if waited != pid or status != 0:
                            raise SystemExit(81)
                    after = counters(root / "memory.events")
                finally:
                    for pid in workers:
                        try:
                            os.kill(pid, signal.SIGKILL)
                        except ProcessLookupError:
                            pass
                    for pid in workers:
                        os.waitpid(pid, 0)
                document = {
                    "kind": mode,
                    "unit": expected_unit,
                    "control_group": control_group,
                    "caps": caps,
                    "workers": worker_count,
                    "bytes_per_worker": bytes_per_worker,
                    "memory_high_delta": after.get("high", 0) - before.get("high", 0),
                    "memory_max_delta": after.get("max", 0) - before.get("max", 0),
                    "memory_oom_delta": after.get("oom", 0) - before.get("oom", 0),
                    "memory_oom_kill_delta": (
                        after.get("oom_kill", 0) - before.get("oom_kill", 0)
                    ),
                }
            print(json.dumps(document, sort_keys=True, separators=(",", ":")))
            '''
        )
        source = (
            inspect.getsource(_strict_memory_worker_hold)
            + "\n"
            + inspect.getsource(_strict_memory_high_gate)
            + "\n"
            + source_body
        ).encode("ascii")

        def run(kind: str, timeout_seconds: float) -> dict[str, object]:
            session_id = uuid.uuid4().hex
            unit = f"required-ci-candidate-{session_id}.scope"
            with _CANDIDATE_SUPPORT._execution_snapshot(
                candidate_root, candidate_sha, probe_source=source
            ) as snapshot:
                runtime_root = snapshot["runtime_root"]
                paths = snapshot["candidate_paths"]
                self.assertIsInstance(runtime_root, Path)
                self.assertIsInstance(paths, dict)
                assert isinstance(runtime_root, Path)
                assert isinstance(paths, dict)
                probe_path = Path(next(iter(paths.values())))
                receipt = _CANDIDATE_SUPPORT._invoke_strict_controller(
                    snapshot,
                    [
                        str(_CANDIDATE_SUPPORT._STRICT_PRIMITIVES["python"]),
                        *_CANDIDATE_SUPPORT._ROOT_PYTHON_ARGUMENTS,
                        str(probe_path),
                        kind,
                        unit,
                        str(runtime_root / "memory-stop"),
                    ],
                    _CANDIDATE_SUPPORT._closed_candidate_environment(
                        None, home=runtime_root, temporary_root=runtime_root
                    ),
                    runtime_root,
                    b"",
                    timeout_seconds=timeout_seconds,
                    registered_session_id=session_id,
                )
                self.assertEqual(receipt.get("status"), "completed", receipt)
                self.assertEqual(receipt.get("cleanup_status"), "complete")
                self.assertEqual(receipt.get("returncode"), 0, receipt)
                self.assertIs(receipt.get("timed_out"), False)
                self.assertIs(receipt.get("process_leak_observed"), False)
                self.assertEqual(
                    _CANDIDATE_SUPPORT._decode_strict_probe_output_text(
                        receipt, "stderr_base64"
                    ),
                    "",
                )
                stdout = _CANDIDATE_SUPPORT._decode_strict_probe_output_text(
                    receipt, "stdout_base64"
                )
                self.assertTrue(stdout.endswith("\n"))
                self.assertEqual(stdout.count("\n"), 1)
                metrics = _validated_systemd_live_metrics(
                    json.loads(stdout), session_id=session_id, kind=kind
                )
                scope = _CANDIDATE_SUPPORT._validated_systemd_scope_document(
                    receipt.get("resource_scope"),
                    session_id=session_id,
                    allow_unbound=False,
                )
                self.assertEqual(scope["unit"], unit)
            deadline = time.monotonic() + 5.0
            self.assertIsNone(
                _CANDIDATE_SUPPORT._query_systemd_scope_lifecycle(
                    unit, deadline=deadline
                )
            )
            self.assertFalse(
                _CANDIDATE_SUPPORT._bound_systemd_scope_present(
                    scope, _CANDIDATE_SUPPORT._STRICT_SYSTEMD_CGROUP_ROOT
                )
            )
            return metrics

        process_metrics = run("process-cpu", 15.0)
        memory_metrics = run("memory", 25.0)
        self.assertNotEqual(process_metrics["unit"], memory_metrics["unit"])

    def test_strict_runtime_live_end_to_end(self) -> None:
        if os.environ.get(REQUIRED_CI_ISOLATION_MODE_ENV) is None:
            self.skipTest(
                "strict live evidence runs only under the trusted supervisor"
            )
        candidate_root, candidate_sha, _binding = (
            _validated_strict_live_repository_binding()
        )
        self._exercise_strict_target_access_policy_blocks_snapshot_write_and_control_read()
        self._exercise_real_watchdog_owner_sigkill_replays_registered_live_ipc_root()
        self._exercise_strict_systemd_scope_aggregate_limits(
            candidate_root, candidate_sha
        )

    def _exercise_strict_target_access_policy_blocks_snapshot_write_and_control_read(
        self,
    ) -> None:
        mode = os.environ.get(REQUIRED_CI_ISOLATION_MODE_ENV)
        if mode is None:
            self.skipTest(
                "strict target credential transition is exercised only by the "
                "trusted Required CI supervisor"
            )
        self.assertEqual(mode, REQUIRED_CI_ISOLATION_MODE)
        if sys.platform != "linux":
            self.skipTest("strict live mount and IPC isolation requires Linux")
        try:
            core_pattern_bytes = Path(
                "/proc/sys/kernel/core_pattern"
            ).read_bytes()
            core_pattern = core_pattern_bytes.decode("ascii")
        except (OSError, UnicodeDecodeError):
            self.fail("strict live host core_pattern is unreadable")
        if core_pattern.endswith("\n"):
            core_pattern = core_pattern[:-1]
        if (
            not core_pattern
            or "\n" in core_pattern
            or "\r" in core_pattern
            or "\x00" in core_pattern
        ):
            self.fail("strict live host core_pattern is malformed")
        if core_pattern.startswith("|"):
            self.fail(
                "strict live core isolation requires a non-piped host "
                "core_pattern because piped handlers bypass RLIMIT_CORE"
            )
        if (
            core_pattern in {".", ".."}
            or "/" in core_pattern
            or not all(
                0x21 <= ord(character) <= 0x7E
                for character in core_pattern
            )
        ):
            self.fail("strict live host core_pattern is unsafe")
        _CANDIDATE_SUPPORT._ensure_strict_backend()

        host_mount_namespace = os.readlink("/proc/self/ns/mnt")
        host_ipc_namespace = os.readlink("/proc/self/ns/ipc")
        realm = _CANDIDATE_SUPPORT._strict_realm()
        target_uid = int(realm["uid"])
        target_gid = int(realm["gid"])

        surface_roots: list[Path] = []
        surface_identities: dict[Path, tuple[int, int]] = {}
        surface_markers: dict[Path, Path] = {}

        def remove_empty_bound_root(
            root: Path, identity: tuple[int, int]
        ) -> None:
            metadata = root.lstat()
            if (metadata.st_dev, metadata.st_ino) != identity:
                raise AssertionError(f"host setup root identity changed: {root}")
            root.rmdir()

        setup_cleanup = contextlib.ExitStack()
        ipc_root_cleanup = contextlib.ExitStack()
        try:
            ipc_root_binding = ipc_root_cleanup.enter_context(
                _CANDIDATE_SUPPORT._registered_live_host_ipc_root()
            )
            ipc_root = _CANDIDATE_SUPPORT._revalidate_registered_live_ipc_root(
                ipc_root_binding
            )
            ipc_root_identity = (
                int(ipc_root_binding["root"]["device"]),
                int(ipc_root_binding["root"]["inode"]),
            )

            def revalidate_ipc_root() -> None:
                selected = (
                    _CANDIDATE_SUPPORT._revalidate_registered_live_ipc_root(
                        ipc_root_binding
                    )
                )
                if selected != ipc_root:
                    raise AssertionError(
                        "strict live IPC root selection changed"
                    )

            revalidate_ipc_root()
            socket_path = ipc_root / "post-seal.sock"
            fifo_path = ipc_root / "post-seal.fifo"
            if len(os.fsencode(socket_path)) >= 104:
                raise AssertionError(
                    "strict live host IPC root produces an unsafe AF_UNIX path length"
                )

            for surface in (
                Path("/tmp"),
                Path("/var/tmp"),
                Path("/dev/shm"),
                Path("/run/lock"),
            ):
                root = Path(
                    tempfile.mkdtemp(prefix="required-ci-private-", dir=surface)
                ).resolve(strict=True)
                metadata = root.lstat()
                if not stat.S_ISDIR(metadata.st_mode) or metadata.st_nlink < 1:
                    raise AssertionError(
                        "strict live host scaffold identity is unsafe"
                    )
                surface_roots.append(root)
                surface_identities[root] = (metadata.st_dev, metadata.st_ino)
                setup_cleanup.callback(
                    remove_empty_bound_root,
                    root,
                    surface_identities[root],
                )
                root.chmod(0o777)
                surface_markers[root] = root / (
                    "posix-shm-private-marker"
                    if surface == Path("/dev/shm")
                    else "candidate-private-marker"
                )

            libc = ctypes.CDLL(None, use_errno=True)
            libc.shmget.argtypes = (ctypes.c_int, ctypes.c_size_t, ctypes.c_int)
            libc.shmget.restype = ctypes.c_int
            libc.shmctl.argtypes = (ctypes.c_int, ctypes.c_int, ctypes.c_void_p)
            libc.shmctl.restype = ctypes.c_int
            libc.mq_unlink.argtypes = (ctypes.c_char_p,)
            libc.mq_unlink.restype = ctypes.c_int

            def remove_setup_sysv(shmid: int) -> None:
                ctypes.set_errno(0)
                if libc.shmctl(shmid, 0, None) != 0:
                    raise OSError(ctypes.get_errno(), "shmctl setup cleanup failed")

            sysv_key = 0
            host_shmid = -1
            for _ in range(64):
                sysv_key = (uuid.uuid4().int & 0x3FFFFFFF) or 1
                ctypes.set_errno(0)
                host_shmid = libc.shmget(
                    sysv_key,
                    4096,
                    0o1000 | 0o2000 | 0o666,
                )
                if host_shmid >= 0:
                    setup_cleanup.callback(remove_setup_sysv, host_shmid)
                    break
                if ctypes.get_errno() != errno.EEXIST:
                    raise OSError(ctypes.get_errno(), "shmget sentinel failed")
            if host_shmid < 0:
                raise AssertionError(
                    "strict live SysV sentinel key inventory exhausted"
                )

            mqueue_name = f"/required-ci-{uuid.uuid4().hex}"
            host_mqueue_path = Path("/dev/mqueue") / mqueue_name[1:]
            if host_mqueue_path.exists():
                raise AssertionError(
                    "strict live POSIX mqueue name unexpectedly exists"
                )
        except BaseException:
            try:
                setup_cleanup.close()
            finally:
                ipc_root_cleanup.close()
            raise
        else:
            setup_cleanup.pop_all()

        trusted_control_relative = (
            TRUSTED_CONTENT_RELATIVE_ROOT
            / "skills/waited-delivery/tests/required_ci_candidate.py"
        ).as_posix()
        go_marker: Path | None = None
        ready_marker: Path | None = None
        explicit_marker: Path | None = None
        listener_created: list[bool] = []
        listener_received: list[bytes] = []
        listener_fifo_remaining: bytes | None = None
        listener_errors: list[BaseException] = []
        listener_nodes: dict[Path, tuple[int, int, int]] = {}
        listener_process: subprocess.Popen[bytes] | None = None
        listener_identity: tuple[int, ...] | None = None
        rw_hint_path = ipc_root / "rw-hint-sentinel"
        rw_hint_identity: tuple[int, int] | None = None
        rw_hint_descriptor: int | None = None
        rw_hint_baseline: bytes | None = None
        completed: subprocess.CompletedProcess[str] | None = None
        helper_source = inspect.cleandoc(
            r'''
            import json
            import os
            from pathlib import Path
            import select
            import signal
            import socket
            import sys
            import time

            if len(sys.argv) != 6 or sys.argv[1] not in ("normal", "hang"):
                raise SystemExit(70)
            mode = sys.argv[1]
            socket_path = Path(sys.argv[2])
            fifo_path = Path(sys.argv[3])
            go_marker = Path(sys.argv[4])
            ready_marker = Path(sys.argv[5])
            if mode == "hang":
                signal.signal(signal.SIGTERM, signal.SIG_IGN)

            deadline = time.monotonic() + 15.0
            while not go_marker.exists():
                readable, _, _ = select.select([0], [], [], 0.05)
                if readable:
                    os.read(0, 16)
                    raise SystemExit(71)
                if time.monotonic() >= deadline:
                    raise SystemExit(72)
            if go_marker.read_text(encoding="utf-8") != "go\n":
                raise SystemExit(73)

            received = []
            with socket.socket(socket.AF_UNIX, socket.SOCK_STREAM) as server:
                server.bind(str(socket_path))
                socket_path.chmod(0o666)
                os.mkfifo(fifo_path, 0o666)
                fifo_path.chmod(0o666)
                fifo_descriptor = os.open(
                    fifo_path, os.O_RDWR | os.O_NONBLOCK
                )
                try:
                    fifo_prefill = b"host-fifo-byte"
                    if os.write(fifo_descriptor, fifo_prefill) != len(fifo_prefill):
                        raise SystemExit(74)
                    server.listen(1)
                    server.settimeout(0.05)
                    nodes = {}
                    for path in (socket_path, fifo_path):
                        metadata = path.lstat()
                        nodes[str(path)] = [
                            metadata.st_dev,
                            metadata.st_ino,
                            metadata.st_mode,
                            metadata.st_uid,
                        ]
                    print(
                        json.dumps(
                            {
                                "go_observed": True,
                                "nodes": nodes,
                                "pid": os.getpid(),
                                "status": "ready",
                            },
                            sort_keys=True,
                        ),
                        flush=True,
                    )
                    ready_marker.write_text("ready\n", encoding="utf-8")
                    while True:
                        readable, _, _ = select.select([0], [], [], 0.05)
                        if readable:
                            command = os.read(0, 16)
                            if mode == "normal":
                                break
                            time.sleep(0.05)
                        try:
                            connection, _ = server.accept()
                        except TimeoutError:
                            pass
                        else:
                            with connection:
                                connection.settimeout(0.5)
                                received.append(connection.recv(16).hex())
                    try:
                        fifo_remaining = os.read(fifo_descriptor, len(fifo_prefill))
                    except BlockingIOError:
                        fifo_remaining = b""
                finally:
                    os.close(fifo_descriptor)
            print(
                json.dumps(
                    {
                        "fifo_remaining": fifo_remaining.hex(),
                        "received": received,
                        "status": "completed",
                    },
                    sort_keys=True,
                ),
                flush=True,
            )
            '''
        ) + "\n"

        def start_host_ipc_helper(
            selected_socket: Path,
            selected_fifo: Path,
            selected_go: Path,
            selected_ready: Path,
            *,
            mode: str,
        ) -> tuple[subprocess.Popen[bytes], tuple[int, ...]]:
            revalidate_ipc_root()
            process = subprocess.Popen(
                [
                    sys.executable,
                    "-I",
                    "-B",
                    "-c",
                    helper_source,
                    mode,
                    str(selected_socket),
                    str(selected_fifo),
                    str(selected_go),
                    str(selected_ready),
                ],
                stdin=subprocess.PIPE,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                start_new_session=True,
            )
            try:
                identity = _CANDIDATE_SUPPORT._process_identity(
                    Path("/proc") / str(process.pid)
                )
                if identity is None or identity[0] != process.pid:
                    raise AssertionError("host IPC helper identity is unavailable")
            except BaseException:
                def kill_unreaped_helper() -> None:
                    if process.poll() is None:
                        try:
                            process.kill()
                        except ProcessLookupError:
                            pass

                kill_unreaped_helper()
                try:
                    process.communicate(timeout=2)
                except subprocess.TimeoutExpired:
                    kill_unreaped_helper()
                    process.communicate(timeout=2)
                if process.poll() is None:
                    raise AssertionError(
                        "host IPC helper could not be reaped after acquisition failure"
                    )
                raise
            return process, identity

        def stop_host_ipc_helper(
            process: subprocess.Popen[bytes],
            identity: tuple[int, ...],
            *,
            expect_graceful: bool,
        ) -> tuple[bytes, bytes]:
            def assert_live_direct_child() -> None:
                observed = _CANDIDATE_SUPPORT._process_identity(
                    Path("/proc") / str(process.pid)
                )
                if process.poll() is not None or observed != identity:
                    raise AssertionError(
                        "host IPC helper is not the live unreaped direct child"
                    )
                children_path = (
                    Path("/proc")
                    / str(process.pid)
                    / "task"
                    / str(process.pid)
                    / "children"
                )
                children = children_path.read_bytes()
                if len(children) > 4096 or children.split():
                    raise AssertionError("host IPC helper has a descendant")

            if process.poll() is None:
                assert_live_direct_child()
                if process.stdin is not None:
                    try:
                        process.stdin.write(b"stop\n")
                        process.stdin.flush()
                    except BrokenPipeError:
                        pass
                    finally:
                        process.stdin.close()
                        process.stdin = None
            try:
                stdout, stderr = process.communicate(timeout=0.5)
            except subprocess.TimeoutExpired:
                assert_live_direct_child()
                process.terminate()
                try:
                    stdout, stderr = process.communicate(timeout=0.5)
                except subprocess.TimeoutExpired:
                    assert_live_direct_child()
                    process.kill()
                    stdout, stderr = process.communicate(timeout=2)
            if (
                process.poll() is None
                or _CANDIDATE_SUPPORT._process_identity(
                    Path("/proc") / str(process.pid)
                )
                == identity
            ):
                raise AssertionError("host IPC helper was not reaped")
            if len(stdout) > 65536 or len(stderr) > 65536:
                raise AssertionError("host IPC helper output exceeded its bound")
            if expect_graceful:
                if process.returncode != 0 or stderr:
                    raise AssertionError(
                        "host IPC helper did not stop cleanly: "
                        + stderr.decode("utf-8", errors="replace")
                    )
            elif process.returncode != -signal.SIGKILL:
                raise AssertionError(
                    "hanging host IPC helper did not require the kill fallback"
                )
            return stdout, stderr

        def parse_host_ipc_helper(
            stdout: bytes,
            expected_paths: tuple[Path, Path],
            expected_pid: int,
            *,
            completed_required: bool,
        ) -> tuple[
            dict[Path, tuple[int, int, int]], list[bytes], bytes | None
        ]:
            try:
                documents = [
                    json.loads(line)
                    for line in stdout.decode("utf-8").splitlines()
                ]
            except (UnicodeDecodeError, json.JSONDecodeError) as error:
                raise AssertionError("host IPC helper output is malformed") from error
            expected_count = 2 if completed_required else 1
            if len(documents) != expected_count:
                raise AssertionError("host IPC helper output count is wrong")
            ready = documents[0]
            if (
                type(ready) is not dict
                or ready.get("status") != "ready"
                or ready.get("pid") != expected_pid
                or ready.get("go_observed") is not True
                or type(ready.get("nodes")) is not dict
            ):
                raise AssertionError("host IPC helper readiness is malformed")
            nodes: dict[Path, tuple[int, int, int]] = {}
            for path in expected_paths:
                value = ready["nodes"].get(str(path))
                if (
                    type(value) is not list
                    or len(value) != 4
                    or any(type(item) is not int for item in value)
                    or value[3] != os.getuid()
                ):
                    raise AssertionError("host IPC helper node binding is malformed")
                nodes[path] = (value[0], value[1], value[2])
            if not completed_required:
                return nodes, [], None
            terminal = documents[1]
            if (
                type(terminal) is not dict
                or terminal.get("status") != "completed"
                or type(terminal.get("received")) is not list
                or type(terminal.get("fifo_remaining")) is not str
                or any(
                    type(value) is not str
                    for value in terminal.get("received", [])
                )
            ):
                raise AssertionError("host IPC helper terminal output is malformed")
            try:
                received = [bytes.fromhex(value) for value in terminal["received"]]
                fifo_remaining = bytes.fromhex(terminal["fifo_remaining"])
            except ValueError as error:
                raise AssertionError(
                    "host IPC helper receipt bytes are malformed"
                ) from error
            return nodes, received, fifo_remaining

        def remove_host_ipc_node(
            path: Path,
            expected: tuple[int, int, int] | None,
            expected_kind,
        ) -> None:
            revalidate_ipc_root()
            root_metadata = ipc_root.lstat()
            if (
                root_metadata.st_dev,
                root_metadata.st_ino,
            ) != ipc_root_identity:
                raise AssertionError("host IPC scaffold identity changed")
            try:
                metadata = path.lstat()
            except FileNotFoundError:
                if expected is not None:
                    raise AssertionError(f"host IPC node disappeared: {path}")
                return
            if expected is not None and (
                metadata.st_dev,
                metadata.st_ino,
                metadata.st_mode,
            ) != expected:
                raise AssertionError(f"host IPC node identity changed: {path}")
            if (
                not expected_kind(metadata.st_mode)
                or metadata.st_uid != os.getuid()
            ):
                raise AssertionError(
                    f"host IPC node ownership/type changed: {path}"
                )
            path.unlink()

        def remove_host_regular(
            path: Path, expected: tuple[int, int] | None
        ) -> None:
            revalidate_ipc_root()
            try:
                metadata = path.lstat()
            except FileNotFoundError:
                if expected is not None:
                    raise AssertionError(f"host IPC marker disappeared: {path}")
                return
            if expected is not None and (
                metadata.st_dev,
                metadata.st_ino,
            ) != expected:
                raise AssertionError(f"host IPC marker identity changed: {path}")
            if (
                not stat.S_ISREG(metadata.st_mode)
                or metadata.st_uid != os.getuid()
                or metadata.st_nlink != 1
            ):
                raise AssertionError(
                    f"host IPC marker ownership/type changed: {path}"
                )
            path.unlink()

        hang_socket = ipc_root / "hang.sock"
        hang_fifo = ipc_root / "hang.fifo"
        hang_go = ipc_root / "hang-go"
        hang_ready = ipc_root / "hang-ready"
        hang_process: subprocess.Popen[bytes] | None = None
        hang_identity: tuple[int, ...] | None = None
        hang_nodes: dict[Path, tuple[int, int, int]] = {}
        hang_go_identity: tuple[int, int] | None = None
        hang_ready_identity: tuple[int, int] | None = None
        hang_cleanup_errors: list[str] = []
        try:
            hang_process, hang_identity = start_host_ipc_helper(
                hang_socket,
                hang_fifo,
                hang_go,
                hang_ready,
                mode="hang",
            )
            hang_go.write_text("go\n", encoding="utf-8")
            metadata = hang_go.lstat()
            hang_go_identity = (metadata.st_dev, metadata.st_ino)
            deadline = time.monotonic() + 5.0
            while not hang_ready.exists():
                if hang_process.poll() is not None:
                    raise AssertionError(
                        "hanging host IPC helper exited before readiness"
                    )
                if time.monotonic() >= deadline:
                    raise AssertionError(
                        "hanging host IPC helper did not become ready"
                    )
                time.sleep(0.01)
            if hang_ready.read_text(encoding="utf-8") != "ready\n":
                raise AssertionError("hanging host IPC helper readiness changed")
            metadata = hang_ready.lstat()
            hang_ready_identity = (metadata.st_dev, metadata.st_ino)
            stdout, stderr = stop_host_ipc_helper(
                hang_process,
                hang_identity,
                expect_graceful=False,
            )
            if stderr:
                raise AssertionError("hanging host IPC helper wrote stderr")
            hang_nodes, received, fifo_remaining = parse_host_ipc_helper(
                stdout,
                (hang_socket, hang_fifo),
                hang_process.pid,
                completed_required=False,
            )
            if received:
                raise AssertionError(
                    "hanging host IPC helper unexpectedly received candidate data"
                )
            if fifo_remaining is not None:
                raise AssertionError(
                    "hanging host IPC helper emitted a terminal FIFO receipt"
                )
        finally:
            if (
                hang_process is not None
                and hang_identity is not None
                and (
                    hang_process.poll() is None
                    or _CANDIDATE_SUPPORT._process_identity(
                        Path("/proc") / str(hang_process.pid)
                    )
                    == hang_identity
                )
            ):
                try:
                    stop_host_ipc_helper(
                        hang_process,
                        hang_identity,
                        expect_graceful=False,
                    )
                except BaseException as error:
                    hang_cleanup_errors.append(str(error))
            helper_terminal = (
                hang_process is None
                or (
                    hang_process.poll() is not None
                    and (
                        hang_identity is None
                        or _CANDIDATE_SUPPORT._process_identity(
                            Path("/proc") / str(hang_process.pid)
                        )
                        != hang_identity
                    )
                )
            )
            if not helper_terminal:
                hang_cleanup_errors.append(
                    "hanging host IPC helper remained active"
                )
            else:
                for path, kind in (
                    (hang_socket, stat.S_ISSOCK),
                    (hang_fifo, stat.S_ISFIFO),
                ):
                    try:
                        remove_host_ipc_node(path, hang_nodes.get(path), kind)
                    except BaseException as error:
                        hang_cleanup_errors.append(str(error))
                for path, expected in (
                    (hang_ready, hang_ready_identity),
                    (hang_go, hang_go_identity),
                ):
                    try:
                        remove_host_regular(path, expected)
                    except BaseException as error:
                        hang_cleanup_errors.append(str(error))
                try:
                    if tuple(ipc_root.iterdir()):
                        raise AssertionError(
                            "hanging host IPC helper left scaffold residue"
                        )
                except BaseException as error:
                    hang_cleanup_errors.append(str(error))
            if hang_cleanup_errors:
                raise AssertionError("; ".join(hang_cleanup_errors))

        try:
            revalidate_ipc_root()
            rw_hint_path.write_bytes(b"required-ci-rw-hint\n")
            rw_hint_path.chmod(0o444)
            metadata = rw_hint_path.lstat()
            if (
                not stat.S_ISREG(metadata.st_mode)
                or metadata.st_uid != os.getuid()
                or metadata.st_nlink != 1
                or stat.S_IMODE(metadata.st_mode) != 0o444
            ):
                raise AssertionError("host fcntl sentinel identity is unsafe")
            rw_hint_identity = (metadata.st_dev, metadata.st_ino)
            rw_hint_descriptor = os.open(
                rw_hint_path,
                os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC,
            )
            try:
                rw_hint_baseline = fcntl.fcntl(
                    rw_hint_descriptor, 1035, bytes(8)
                )
            except OSError as error:
                raise AssertionError(
                    "strict live host filesystem does not support F_GET_RW_HINT"
                ) from error
            if type(rw_hint_baseline) is not bytes or len(rw_hint_baseline) != 8:
                raise AssertionError("strict live F_GET_RW_HINT result is malformed")
            with _CANDIDATE_SUPPORT.candidate_fixture_directory(
                "required-ci-access-policy-"
            ) as temporary_directory, _CANDIDATE_SUPPORT.candidate_fixture_directory(
                "required-ci-access-allowed-"
            ) as explicit_directory:
                _, candidate_root = self.prepare_roots(temporary_directory)
                explicit_root = Path(explicit_directory).resolve(strict=True)
                go_marker = explicit_root / "candidate-go"
                ready_marker = explicit_root / "host-ipc-ready"
                explicit_marker = explicit_root / "allowed-write"
                git_root = explicit_root / "git-fixture"
                git_root.mkdir()
                (git_root / "tracked.txt").write_text(
                    "tracked\n", encoding="utf-8"
                )
                trusted_git = _CANDIDATE_SUPPORT.TRUSTED_GIT_EXECUTABLE
                git_environment = os.environ.copy()
                git_environment.update(
                    {
                        "GIT_CONFIG_GLOBAL": "/dev/null",
                        "GIT_CONFIG_NOSYSTEM": "1",
                        "GIT_OPTIONAL_LOCKS": "0",
                        "GIT_TERMINAL_PROMPT": "0",
                    }
                )
                subprocess.run(
                    [
                        trusted_git,
                        "init",
                        "--quiet",
                        "--object-format=sha1",
                        str(git_root),
                    ],
                    check=True,
                    capture_output=True,
                    env=git_environment,
                    timeout=5,
                )
                subprocess.run(
                    [trusted_git, "-C", str(git_root), "add", "tracked.txt"],
                    check=True,
                    capture_output=True,
                    env=git_environment,
                    timeout=5,
                )
                subprocess.run(
                    [
                        trusted_git,
                        "-c",
                        "user.name=Required CI",
                        "-c",
                        "user.email=required-ci@example.invalid",
                        "-c",
                        "commit.gpgSign=false",
                        "-C",
                        str(git_root),
                        "commit",
                        "--quiet",
                        "-m",
                        "fixture",
                    ],
                    check=True,
                    capture_output=True,
                    env=git_environment,
                    timeout=5,
                )
                candidate_content_root = distribution_content_root(candidate_root)
                runner_path = (
                    candidate_content_root
                    / "skills/waited-delivery/scripts/waited_delivery_runner.py"
                )
                candidate_source = inspect.cleandoc(
                        r'''
                        import ctypes
                        from compression import zstd
                        import errno
                        import fcntl
                        import json
                        import os
                        from pathlib import Path
                        import resource
                        import signal
                        import socket
                        import stat
                        import struct
                        import subprocess
                        import sys
                        import termios
                        import time

                        if len(sys.argv) != 10:
                            raise SystemExit(90)
                        explicit_root = Path(sys.argv[1])
                        surface_roots = tuple(Path(value) for value in sys.argv[2:6])
                        socket_path = Path(__REQUIRED_CI_SOCKET_PATH__)
                        fifo_path = Path(__REQUIRED_CI_FIFO_PATH__)
                        trusted_git = __REQUIRED_CI_GIT_PATH__
                        rw_hint_path = Path(__REQUIRED_CI_RW_HINT_PATH__)
                        sysv_key = int(sys.argv[6])
                        trusted_relative = Path(sys.argv[7])
                        host_ipc_namespace = sys.argv[8]
                        mqueue_name = sys.argv[9]
                        candidate_path = Path(__file__)
                        candidate_root = next(
                            parent for parent in candidate_path.parents
                            if parent.name == "candidate-code"
                        )
                        trusted_control = (
                            candidate_root.parent / "trusted-control" / trusted_relative
                        )

                        try:
                            candidate_path.write_bytes(b"candidate mutation\n")
                        except PermissionError:
                            write_status = "write-denied"
                        else:
                            write_status = "write-allowed"
                        try:
                            trusted_control.read_bytes()
                        except PermissionError:
                            read_status = "read-denied"
                        else:
                            read_status = "read-allowed"
                        stdlib_path = Path(os.__file__)
                        stdlib_status = (
                            "stdlib-readable"
                            if stdlib_path.read_bytes()
                            else "stdlib-empty"
                        )
                        try:
                            with stdlib_path.open("ab"):
                                pass
                        except PermissionError:
                            stdlib_write_status = "stdlib-write-denied"
                        else:
                            stdlib_write_status = "stdlib-write-allowed"
                        try:
                            with Path(sys.executable).open("ab"):
                                pass
                        except PermissionError:
                            interpreter_write_status = "interpreter-write-denied"
                        else:
                            interpreter_write_status = "interpreter-write-allowed"

                        workspace_marker = Path.cwd() / "workspace-write"
                        runtime_marker = Path(os.environ["TMPDIR"]) / "runtime-write"
                        explicit_marker = explicit_root / "allowed-write"
                        for marker, payload in (
                            (workspace_marker, "workspace\n"),
                            (runtime_marker, "runtime\n"),
                            (explicit_marker, "explicit\n"),
                        ):
                            marker.write_text(payload, encoding="utf-8")
                            if marker.read_text(encoding="utf-8") != payload:
                                raise SystemExit(91)
                        allowed_writes = {
                            "explicit": explicit_marker.read_text(encoding="utf-8"),
                            "runtime": runtime_marker.read_text(encoding="utf-8"),
                            "workspace": workspace_marker.read_text(encoding="utf-8"),
                        }

                        private_markers = {}
                        for index, root in enumerate(surface_roots):
                            root.mkdir(mode=0o700, parents=True, exist_ok=True)
                            name = (
                                "posix-shm-private-marker"
                                if index == 2
                                else "candidate-private-marker"
                            )
                            marker = root / name
                            marker.write_text("private\n", encoding="utf-8")
                            private_markers[str(marker)] = marker.read_text(
                                encoding="utf-8"
                            )

                        go_marker = explicit_root / "candidate-go"
                        ready_marker = explicit_root / "host-ipc-ready"
                        go_marker.write_text("go\n", encoding="utf-8")
                        deadline = time.monotonic() + 15.0
                        while not ready_marker.exists():
                            if time.monotonic() >= deadline:
                                raise SystemExit(92)
                            time.sleep(0.01)
                        if ready_marker.read_text(encoding="utf-8") != "ready\n":
                            raise SystemExit(92)
                        socket_metadata = socket_path.lstat()
                        fifo_metadata = fifo_path.lstat()
                        post_seal_nodes_visible = (
                            stat.S_ISSOCK(socket_metadata.st_mode)
                            and stat.S_IMODE(socket_metadata.st_mode) == 0o666
                            and stat.S_ISFIFO(fifo_metadata.st_mode)
                            and stat.S_IMODE(fifo_metadata.st_mode) == 0o666
                        )
                        if not post_seal_nodes_visible:
                            raise SystemExit(92)

                        def operation_errno(operation):
                            try:
                                operation()
                            except OSError as error:
                                return error.errno
                            return 0

                        limits_descriptor = os.open(
                            "/proc/self/limits",
                            os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC,
                        )
                        try:
                            limits_bytes = os.read(limits_descriptor, 65537)
                        finally:
                            os.close(limits_descriptor)
                        if not limits_bytes or len(limits_bytes) > 65536:
                            raise SystemExit(92)
                        limits_lines = limits_bytes.decode("ascii").splitlines()
                        core_limit_rows = [
                            line.split()
                            for line in limits_lines
                            if line.startswith("Max core file size ")
                        ]
                        if len(core_limit_rows) != 1:
                            raise SystemExit(92)
                        core_limit_fields = core_limit_rows[0]
                        if core_limit_fields[-3:] != ["1", "1", "bytes"]:
                            raise SystemExit(92)
                        core_limits = core_limit_fields[-3:]

                        core_pattern_descriptor = os.open(
                            "/proc/sys/kernel/core_pattern",
                            os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC,
                        )
                        try:
                            core_pattern_bytes = os.read(
                                core_pattern_descriptor, 4097
                            )
                        finally:
                            os.close(core_pattern_descriptor)
                        if not core_pattern_bytes or len(core_pattern_bytes) > 4096:
                            raise SystemExit(92)
                        core_pattern = core_pattern_bytes.decode("ascii")
                        if core_pattern.endswith("\n"):
                            core_pattern = core_pattern[:-1]
                        if (
                            not core_pattern
                            or "\n" in core_pattern
                            or "\r" in core_pattern
                            or "\x00" in core_pattern
                        ):
                            raise SystemExit(92)
                        if core_pattern.startswith("|"):
                            raise SystemExit(92)
                        elif (
                            core_pattern in {".", ".."}
                            or "/" in core_pattern
                            or not all(
                                0x21 <= ord(character) <= 0x7E
                                for character in core_pattern
                            )
                        ):
                            raise SystemExit(92)
                        setrlimit_errno = operation_errno(
                            lambda: resource.setrlimit(
                                resource.RLIMIT_CORE, (0, 0)
                            )
                        )
                        prlimit_errno = operation_errno(
                            lambda: resource.prlimit(
                                0, resource.RLIMIT_CORE, (0, 0)
                            )
                        )

                        crash_root = explicit_root / "core-crash"
                        crash_root.mkdir(mode=0o700)
                        crash = subprocess.run(
                            [
                                sys.executable,
                                "-I",
                                "-B",
                                "-c",
                                "import ctypes; ctypes.string_at(0)",
                            ],
                            check=False,
                            cwd=crash_root,
                            stdin=subprocess.DEVNULL,
                            stdout=subprocess.DEVNULL,
                            stderr=subprocess.DEVNULL,
                            timeout=5,
                        )
                        core_files = []
                        for core_file in sorted(crash_root.iterdir()):
                            core_metadata = core_file.lstat()
                            if (
                                not stat.S_ISREG(core_metadata.st_mode)
                                or core_metadata.st_nlink != 1
                                or core_metadata.st_size > 1
                            ):
                                raise SystemExit(92)
                            core_files.append(
                                {"name": core_file.name, "size": core_metadata.st_size}
                            )
                        if len(core_files) > 1:
                            raise SystemExit(92)
                        core_returncode = crash.returncode

                        def pathname_socket_operation():
                            candidate_socket = socket.socket(
                                socket.AF_UNIX, socket.SOCK_STREAM
                            )
                            try:
                                candidate_socket.connect(str(socket_path))
                                candidate_socket.sendall(b"socket")
                            finally:
                                candidate_socket.close()

                        def socketpair_operation():
                            first, second = socket.socketpair()
                            try:
                                first.sendall(b"pair")
                            finally:
                                first.close()
                                second.close()

                        def fifo_operation():
                            descriptor = os.open(
                                fifo_path, os.O_WRONLY | os.O_NONBLOCK
                            )
                            try:
                                os.write(descriptor, b"fifo")
                            finally:
                                os.close(descriptor)

                        def fifo_read_operation():
                            descriptor = os.open(
                                fifo_path, os.O_RDONLY | os.O_NONBLOCK
                            )
                            try:
                                os.read(descriptor, 64)
                            finally:
                                os.close(descriptor)

                        socket_errno = operation_errno(pathname_socket_operation)
                        socketpair_errno = operation_errno(socketpair_operation)
                        fifo_errno = operation_errno(fifo_operation)
                        fifo_read_errno = operation_errno(fifo_read_operation)

                        ipc_root = socket_path.parent
                        candidate_create = ipc_root / "candidate-create"
                        candidate_directory = ipc_root / "candidate-directory"
                        candidate_symlink = ipc_root / "candidate-symlink"
                        candidate_rename = ipc_root / "candidate-renamed.sock"

                        def ipc_create_operation():
                            descriptor = os.open(
                                candidate_create,
                                os.O_WRONLY | os.O_CREAT | os.O_EXCL,
                                0o600,
                            )
                            os.close(descriptor)

                        ipc_policy = {
                            "chmod": operation_errno(lambda: ipc_root.chmod(0o700)),
                            "create": operation_errno(ipc_create_operation),
                            "list": operation_errno(lambda: tuple(ipc_root.iterdir())),
                            "mkdir": operation_errno(
                                lambda: candidate_directory.mkdir(mode=0o700)
                            ),
                            "rename": operation_errno(
                                lambda: socket_path.rename(candidate_rename)
                            ),
                            "symlink": operation_errno(
                                lambda: candidate_symlink.symlink_to(socket_path.name)
                            ),
                        }

                        link_source = explicit_root / "link-source"
                        link_target = explicit_root / "link-target"
                        link_source.write_text("source\n", encoding="utf-8")
                        link_errno = operation_errno(
                            lambda: os.link(link_source, link_target)
                        )

                        rw_hint_descriptor = os.open(
                            rw_hint_path,
                            os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC,
                        )
                        try:
                            rw_hint_before = fcntl.fcntl(
                                rw_hint_descriptor, 1035, bytes(8)
                            )
                            selected_hint = (
                                4 if struct.unpack("=Q", rw_hint_before)[0] == 5 else 5
                            )
                            rw_hint_set_errno = operation_errno(
                                lambda: fcntl.fcntl(
                                    rw_hint_descriptor,
                                    1036,
                                    struct.pack("=Q", selected_hint),
                                )
                            )
                        finally:
                            os.close(rw_hint_descriptor)

                        ioctl_read, ioctl_write = os.pipe()
                        try:
                            tcgets_errno = operation_errno(
                                lambda: fcntl.ioctl(
                                    ioctl_read,
                                    termios.TCGETS,
                                    bytearray(64),
                                    True,
                                )
                            )
                            arbitrary_ioctl_errno = operation_errno(
                                lambda: fcntl.ioctl(
                                    ioctl_read,
                                    0x12345678,
                                    bytearray(64),
                                    True,
                                )
                            )
                        finally:
                            os.close(ioctl_read)
                            os.close(ioctl_write)

                        libc = ctypes.CDLL(None, use_errno=True)
                        libc.syscall.restype = ctypes.c_long
                        libc.shmget.argtypes = (
                            ctypes.c_int,
                            ctypes.c_size_t,
                            ctypes.c_int,
                        )
                        libc.shmget.restype = ctypes.c_int

                        machine = os.uname().machine
                        syscall_numbers = {
                            "x86_64": (272, 435, 250, 425, 321),
                            "aarch64": (97, 435, 219, 425, 280),
                        }.get(machine)
                        if syscall_numbers is None:
                            raise SystemExit(93)

                        def syscall_errno(number, *arguments):
                            ctypes.set_errno(0)
                            result = libc.syscall(number, *arguments)
                            return 0 if result >= 0 else ctypes.get_errno()

                        (
                            unshare_number,
                            clone3_number,
                            keyctl_number,
                            io_uring_number,
                            bpf_number,
                        ) = syscall_numbers
                        unshare_errno = syscall_errno(unshare_number, 0x08000000)
                        clone3_errno = syscall_errno(clone3_number, 0, 0)
                        keyctl_errno = syscall_errno(keyctl_number, 0, 0, 0, 0, 0)
                        io_uring_errno = syscall_errno(io_uring_number, 1, 0)
                        bpf_errno = syscall_errno(bpf_number, 0x7FFFFFFF, 0, 0)

                        ctypes.set_errno(0)
                        observed_shmid = libc.shmget(sysv_key, 0, 0)
                        sysv_lookup_errno = (
                            0 if observed_shmid >= 0 else ctypes.get_errno()
                        )
                        private_shmid = -1
                        if sysv_lookup_errno == errno.ENOENT:
                            ctypes.set_errno(0)
                            private_shmid = libc.shmget(
                                sysv_key,
                                4096,
                                0o1000 | 0o2000 | 0o600,
                            )
                            if private_shmid < 0:
                                raise OSError(
                                    ctypes.get_errno(), "private shmget failed"
                                )

                        candidate_ipc_namespace = os.readlink("/proc/self/ns/ipc")
                        mqueue_created = False
                        if candidate_ipc_namespace != host_ipc_namespace:
                            libc.mq_open.argtypes = (
                                ctypes.c_char_p,
                                ctypes.c_int,
                                ctypes.c_uint,
                                ctypes.c_void_p,
                            )
                            libc.mq_open.restype = ctypes.c_int
                            libc.mq_close.argtypes = (ctypes.c_int,)
                            libc.mq_close.restype = ctypes.c_int
                            ctypes.set_errno(0)
                            queue = libc.mq_open(
                                mqueue_name.encode("ascii"),
                                os.O_CREAT | os.O_EXCL | os.O_RDWR | os.O_CLOEXEC,
                                0o600,
                                None,
                            )
                            if queue < 0:
                                raise OSError(
                                    ctypes.get_errno(), "private mq_open failed"
                                )
                            if libc.mq_close(queue) != 0:
                                raise OSError(
                                    ctypes.get_errno(), "private mq_close failed"
                                )
                            mqueue_created = True

                        subprocess_result = subprocess.run(
                            [
                                sys.executable,
                                "-I",
                                "-B",
                                "-c",
                                "print('subprocess-ok')",
                            ],
                            check=True,
                            capture_output=True,
                            text=True,
                        )
                        if subprocess_result.stdout != "subprocess-ok\n":
                            raise SystemExit("subprocess-output")
                        subprocess.run(
                            [
                                sys.executable,
                                "-I",
                                "-B",
                                "-c",
                                "raise SystemExit(0)",
                            ],
                            check=True,
                            stdin=subprocess.DEVNULL,
                            stdout=subprocess.DEVNULL,
                            stderr=subprocess.DEVNULL,
                        )
                        with open("/dev/null", "rb", buffering=0) as null_read:
                            if null_read.read(1) != b"":
                                raise SystemExit("devnull-read")
                        with open("/dev/null", "wb", buffering=0) as null_write:
                            if null_write.write(b"x") != 1:
                                raise SystemExit("devnull-write")

                        def devzero_operation():
                            descriptor = os.open(
                                "/dev/zero", os.O_RDONLY | os.O_CLOEXEC
                            )
                            os.close(descriptor)

                        devzero_errno = operation_errno(devzero_operation)

                        entrypoint_usage = {}
                        for name in (
                            "waited_delivery_bridge.py",
                            "waited_delivery_hook_adapter.py",
                        ):
                            entrypoint = candidate_path.with_name(name)
                            completed = subprocess.run(
                                [
                                    sys.executable,
                                    "-I",
                                    "-B",
                                    str(entrypoint),
                                    "--help",
                                ],
                                check=True,
                                capture_output=True,
                                text=True,
                                timeout=5,
                            )
                            first_line = completed.stdout.splitlines()[:1]
                            expected_prefix = f"usage: {name} "
                            failure = (
                                "stderr" if completed.stderr else
                                "size" if len(completed.stdout.encode("utf-8")) > 65536 else
                                "line" if len(first_line) != 1 else
                                "prefix" if not first_line[0].startswith(expected_prefix) else
                                None
                            )
                            if failure is not None:
                                raise SystemExit(f"entrypoint-help:{name}:{failure}")
                            entrypoint_usage[name] = first_line[0]

                        zstd_payload = b"required-ci-zstd-round-trip\n" * 32
                        zstd_encoded = zstd.compress(zstd_payload)
                        if (
                            not zstd_encoded
                            or zstd.decompress(zstd_encoded) != zstd_payload
                        ):
                            raise SystemExit("zstd-roundtrip")

                        git_root = explicit_root / "git-fixture"
                        os.environ["GIT_OPTIONAL_LOCKS"] = "0"
                        git_prefix = [
                            trusted_git,
                            "--no-pager",
                            "-c",
                            "core.hooksPath=/dev/null",
                            "-c",
                            "core.attributesFile=/dev/null",
                            "-c",
                            "core.fsmonitor=false",
                            "-C",
                            str(git_root),
                        ]

                        def run_git(arguments):
                            completed = subprocess.run(
                                [*git_prefix, *arguments],
                                check=True,
                                capture_output=True,
                                timeout=5,
                            )
                            if (
                                len(completed.stdout) > 65536
                                or len(completed.stderr) > 65536
                                or completed.stderr
                            ):
                                raise SystemExit("git-output")
                            return completed.stdout

                        git_head = run_git(
                            ["rev-parse", "--verify", "HEAD^{commit}"]
                        ).decode("ascii").strip()
                        git_status = run_git(
                            ["status", "--porcelain=v1", "--untracked-files=no"]
                        ).decode("utf-8")
                        git_tree = run_git(
                            ["ls-tree", "--name-only", "HEAD"]
                        ).decode("utf-8")
                        git_archive = run_git(["archive", "--format=tar", "HEAD"])
                        git_blob = run_git(
                            ["cat-file", "blob", "HEAD:tracked.txt"]
                        ).decode("utf-8")

                        status = {}
                        with open("/proc/self/status", encoding="ascii") as status_file:
                            for line in status_file:
                                if ":" in line:
                                    key, value = line.split(":", 1)
                                    status[key] = value.strip()

                        mount_records = []
                        with open("/proc/self/mountinfo", encoding="utf-8") as mountinfo:
                            for line in mountinfo:
                                fields = line.split()
                                separator = fields.index("-")
                                mount_records.append({
                                    "id": int(fields[0]),
                                    "mountpoint": fields[4],
                                    "options": fields[5].split(","),
                                    "filesystem": fields[separator + 1],
                                    "source": fields[separator + 2],
                                })
                        if any(
                            record["mountpoint"]
                            in {
                                "/tmp/required-ci-alias-probe-source",
                                "/tmp/required-ci-alias-probe-target",
                            }
                            for record in mount_records
                        ):
                            raise SystemExit(94)
                        dev_shm_mounts = [
                            record
                            for record in mount_records
                            if record["mountpoint"] == "/dev/shm"
                            and record["filesystem"] == "tmpfs"
                            and record["source"] == "required-ci-private"
                            and "rw" in record["options"]
                            and "nodev" in record["options"]
                        ]
                        if len(dev_shm_mounts) != 1:
                            raise SystemExit(94)
                        dev_shm_mount = dev_shm_mounts[0]

                        null_descriptor = os.open(
                            "/dev/null",
                            getattr(os, "O_PATH")
                            | os.O_NOFOLLOW
                            | os.O_CLOEXEC,
                        )
                        try:
                            null_metadata = os.fstat(null_descriptor)
                        finally:
                            os.close(null_descriptor)
                        devnull_mounts = [
                            record
                            for record in mount_records
                            if record["mountpoint"] == "/dev/null"
                            and "ro" in record["options"]
                            and "nodev" not in record["options"]
                        ]
                        if (
                            len(devnull_mounts) != 1
                            or not stat.S_ISCHR(null_metadata.st_mode)
                        ):
                            raise SystemExit(94)
                        devnull_mount = devnull_mounts[0]
                        devnull_device = {
                            "gid": null_metadata.st_gid,
                            "major": os.major(null_metadata.st_rdev),
                            "minor": os.minor(null_metadata.st_rdev),
                            "mode": stat.S_IMODE(null_metadata.st_mode),
                            "uid": null_metadata.st_uid,
                        }

                        sysctls = {}
                        for path in (
                            "/proc/sys/kernel/shmmax",
                            "/proc/sys/kernel/shmall",
                            "/proc/sys/kernel/shmmni",
                            "/proc/sys/kernel/msgmax",
                            "/proc/sys/kernel/msgmnb",
                            "/proc/sys/kernel/msgmni",
                            "/proc/sys/kernel/sem",
                            "/proc/sys/fs/mqueue/queues_max",
                            "/proc/sys/fs/mqueue/msg_max",
                            "/proc/sys/fs/mqueue/msgsize_max",
                            "/proc/sys/fs/mqueue/msg_default",
                            "/proc/sys/fs/mqueue/msgsize_default",
                        ):
                            sysctls[path] = " ".join(
                                Path(path).read_text(encoding="ascii").split()
                            )

                        result = {
                            "allowed_writes": allowed_writes,
                            "arbitrary_ioctl_errno": arbitrary_ioctl_errno,
                            "bpf_errno": bpf_errno,
                            "dev_shm_mount": dev_shm_mount,
                            "devnull_device": devnull_device,
                            "devnull_mount": devnull_mount,
                            "devnull_subprocess": True,
                            "devzero_errno": devzero_errno,
                            "entrypoint_usage": entrypoint_usage,
                            "fifo_errno": fifo_errno,
                            "fifo_read_errno": fifo_read_errno,
                            "ids": [
                                os.getuid(),
                                os.geteuid(),
                                os.getgid(),
                                os.getegid(),
                            ],
                            "interpreter_write_status": interpreter_write_status,
                            "ipc_namespace": candidate_ipc_namespace,
                            "io_uring_errno": io_uring_errno,
                            "ipc_root_policy": ipc_policy,
                            "git": {
                                "archive_size": len(git_archive),
                                "blob": git_blob,
                                "head": git_head,
                                "status": git_status,
                                "tree": git_tree,
                            },
                            "keyctl_errno": keyctl_errno,
                            "link_errno": link_errno,
                            "clone3_errno": clone3_errno,
                            "core_files": core_files,
                            "core_limits": core_limits,
                            "core_pattern": core_pattern,
                            "core_returncode": core_returncode,
                            "mqueue_created": mqueue_created,
                            "mqueue_visible": Path(
                                "/dev/mqueue", mqueue_name[1:]
                            ).exists(),
                            "mount_namespace": os.readlink("/proc/self/ns/mnt"),
                            "no_new_privs": status.get("NoNewPrivs"),
                            "post_seal_nodes_visible": post_seal_nodes_visible,
                            "prlimit_errno": prlimit_errno,
                            "private_markers": private_markers,
                            "read_status": read_status,
                            "rw_hint_before": rw_hint_before.hex(),
                            "rw_hint_set_errno": rw_hint_set_errno,
                            "runtime": sys.executable,
                            "seccomp": status.get("Seccomp"),
                            "seccomp_filters": status.get("Seccomp_filters"),
                            "setrlimit_errno": setrlimit_errno,
                            "socket_errno": socket_errno,
                            "socketpair_errno": socketpair_errno,
                            "stdlib_status": stdlib_status,
                            "stdlib_write_status": stdlib_write_status,
                            "subprocess": subprocess_result.stdout,
                            "sysctls": sysctls,
                            "sysv_private_created": private_shmid >= 0,
                            "sysv_lookup_errno": sysv_lookup_errno,
                            "tcgets_errno": tcgets_errno,
                            "unshare_errno": unshare_errno,
                            "version": ".".join(map(str, sys.version_info[:3])),
                            "write_status": write_status,
                            "zstd": {
                                "compressed_size": len(zstd_encoded),
                                "payload_size": len(zstd_payload),
                            },
                        }
                        print(json.dumps(result, sort_keys=True))
                        if (
                            result["ids"]
                            != [os.getuid(), os.getuid(), os.getgid(), os.getgid()]
                            or write_status != "write-denied"
                            or read_status != "read-denied"
                            or stdlib_status != "stdlib-readable"
                            or stdlib_write_status != "stdlib-write-denied"
                            or interpreter_write_status
                            != "interpreter-write-denied"
                            or set(private_markers.values()) != {"private\n"}
                            or socket_errno != errno.EACCES
                            or socketpair_errno != errno.EACCES
                            or fifo_errno != errno.EACCES
                            or fifo_read_errno != errno.EACCES
                            or ipc_policy
                            != {
                                "chmod": errno.EPERM,
                                "create": errno.EACCES,
                                "list": errno.EACCES,
                                "mkdir": errno.EACCES,
                                "rename": errno.EACCES,
                                "symlink": errno.EACCES,
                            }
                            or link_errno != errno.EACCES
                            or unshare_errno != errno.EACCES
                            or clone3_errno != errno.ENOSYS
                            or core_limits != ["1", "1", "bytes"]
                            or core_returncode != -signal.SIGSEGV
                            or len(core_files) > 1
                            or setrlimit_errno != errno.EACCES
                            or prlimit_errno != errno.EACCES
                            or keyctl_errno != errno.EACCES
                            or io_uring_errno != errno.EACCES
                            or tcgets_errno != errno.EACCES
                            or arbitrary_ioctl_errno != errno.EACCES
                            or bpf_errno != errno.EACCES
                            or devzero_errno != errno.EACCES
                            or devnull_mount["mountpoint"] != "/dev/null"
                            or "ro" not in devnull_mount["options"]
                            or "nodev" in devnull_mount["options"]
                            or devnull_device
                            != {
                                "gid": 0,
                                "major": 1,
                                "minor": 3,
                                "mode": 0o666,
                                "uid": 0,
                            }
                            or rw_hint_set_errno != errno.EACCES
                            or sysv_lookup_errno != errno.ENOENT
                            or private_shmid < 0
                            or not mqueue_created
                            or not result["mqueue_visible"]
                            or subprocess_result.stdout != "subprocess-ok\n"
                            or git_status
                            or git_tree != "tracked.txt\n"
                            or git_blob != "tracked\n"
                            or len(git_head) != 40
                            or not git_archive
                        ):
                            raise SystemExit(95)
                        '''
                    )
                candidate_source = candidate_source.replace(
                    "__REQUIRED_CI_SOCKET_PATH__", repr(str(socket_path))
                ).replace(
                    "__REQUIRED_CI_FIFO_PATH__", repr(str(fifo_path))
                ).replace(
                    "__REQUIRED_CI_GIT_PATH__", repr(trusted_git)
                ).replace(
                    "__REQUIRED_CI_RW_HINT_PATH__", repr(str(rw_hint_path))
                )
                self.assertNotIn("/proc/self/fdinfo/", candidate_source)
                runner_path.write_text(
                    candidate_source + "\n",
                    encoding="utf-8",
                )
                for relative_path in _CANDIDATE_SUPPORT.CANDIDATE_SCRIPT_RELATIVE_PATHS:
                    if relative_path.name != runner_path.name:
                        (candidate_content_root / relative_path).write_bytes(
                            (TRUSTED_CONTENT_ROOT / relative_path).read_bytes()
                        )
                candidate_sha = self.initialize_candidate_checkout(candidate_root)
                listener_process, listener_identity = start_host_ipc_helper(
                    socket_path,
                    fifo_path,
                    go_marker,
                    ready_marker,
                    mode="normal",
                )
                try:
                    with mock.patch.dict(
                        os.environ,
                        {
                            REQUIRED_CI_CANDIDATE_ROOT_ENV: str(candidate_root),
                            REQUIRED_CI_CANDIDATE_SHA_ENV: candidate_sha,
                        },
                        clear=False,
                    ):
                        revalidate_ipc_root()
                        completed = _CANDIDATE_SUPPORT.run_candidate_python(
                            runner_path,
                            arguments=(
                                str(explicit_root),
                                *(str(root) for root in surface_roots),
                                str(sysv_key),
                                trusted_control_relative,
                                host_ipc_namespace,
                                mqueue_name,
                            ),
                            writable_roots=(explicit_root,),
                            readable_roots=(rw_hint_path,),
                        )
                finally:
                    try:
                        helper_stdout, helper_stderr = stop_host_ipc_helper(
                            listener_process,
                            listener_identity,
                            expect_graceful=True,
                        )
                        (
                            listener_nodes,
                            listener_received,
                            listener_fifo_remaining,
                        ) = parse_host_ipc_helper(
                            helper_stdout,
                            (socket_path, fifo_path),
                            listener_process.pid,
                            completed_required=True,
                        )
                        if helper_stderr:
                            raise AssertionError(
                                "host IPC helper wrote unexpected stderr"
                            )
                        listener_created.append(True)
                    except BaseException as error:
                        listener_errors.append(error)

                self.assertIsNotNone(listener_process.returncode)
                self.assertNotEqual(
                    _CANDIDATE_SUPPORT._process_identity(
                        Path("/proc") / str(listener_process.pid)
                    ),
                    listener_identity,
                )
                self.assertFalse(listener_errors, listener_errors)
                self.assertEqual(listener_created, [True])
                self.assertEqual(listener_received, [])
                self.assertEqual(listener_fifo_remaining, b"host-fifo-byte")
                self.assertEqual(set(listener_nodes), {socket_path, fifo_path})
                assert completed is not None
                self.assertEqual(completed.returncode, 0, completed.stderr)
                result = json.loads(completed.stdout)
                self.assertEqual(
                    result["ids"],
                    [target_uid, target_uid, target_gid, target_gid],
                )
                self.assertEqual(result["write_status"], "write-denied")
                self.assertEqual(result["read_status"], "read-denied")
                self.assertEqual(result["stdlib_status"], "stdlib-readable")
                self.assertEqual(
                    result["stdlib_write_status"], "stdlib-write-denied"
                )
                self.assertEqual(
                    result["interpreter_write_status"],
                    "interpreter-write-denied",
                )
                self.assertEqual(
                    result["runtime"], str(Path(sys.executable).resolve(strict=True))
                )
                self.assertEqual(
                    result["version"], ".".join(map(str, sys.version_info[:3]))
                )
                self.assertEqual(result["mount_namespace"] == host_mount_namespace, False)
                self.assertEqual(result["ipc_namespace"] == host_ipc_namespace, False)
                self.assertEqual(result["no_new_privs"], "1")
                self.assertIs(result["post_seal_nodes_visible"], True)
                self.assertEqual(result["seccomp"], "2")
                self.assertGreaterEqual(int(result["seccomp_filters"]), 1)
                self.assertEqual(result["socket_errno"], errno.EACCES)
                self.assertEqual(result["socketpair_errno"], errno.EACCES)
                self.assertEqual(result["fifo_errno"], errno.EACCES)
                self.assertEqual(result["fifo_read_errno"], errno.EACCES)
                self.assertEqual(
                    result["ipc_root_policy"],
                    {
                        "chmod": errno.EPERM,
                        "create": errno.EACCES,
                        "list": errno.EACCES,
                        "mkdir": errno.EACCES,
                        "rename": errno.EACCES,
                        "symlink": errno.EACCES,
                    },
                )
                self.assertEqual(result["link_errno"], errno.EACCES)
                self.assertEqual(result["unshare_errno"], errno.EACCES)
                self.assertEqual(result["clone3_errno"], errno.ENOSYS)
                self.assertEqual(result["io_uring_errno"], errno.EACCES)
                self.assertEqual(result["keyctl_errno"], errno.EACCES)
                self.assertEqual(result["tcgets_errno"], errno.EACCES)
                self.assertEqual(
                    result["arbitrary_ioctl_errno"], errno.EACCES
                )
                self.assertEqual(result["bpf_errno"], errno.EACCES)
                self.assertEqual(result["core_limits"], ["1", "1", "bytes"])
                self.assertEqual(result["core_returncode"], -signal.SIGSEGV)
                self.assertLessEqual(len(result["core_files"]), 1)
                for core_file in result["core_files"]:
                    self.assertEqual(set(core_file), {"name", "size"})
                    self.assertIsInstance(core_file["name"], str)
                    self.assertLessEqual(core_file["size"], 1)
                core_pattern = result["core_pattern"]
                self.assertIsInstance(core_pattern, str)
                self.assertFalse(core_pattern.startswith("|"))
                self.assertNotIn(core_pattern, {".", ".."})
                self.assertNotIn("/", core_pattern)
                self.assertTrue(
                    all(
                        0x21 <= ord(character) <= 0x7E
                        for character in core_pattern
                    )
                )
                self.assertEqual(result["setrlimit_errno"], errno.EACCES)
                self.assertEqual(result["prlimit_errno"], errno.EACCES)
                actual_core_files = []
                for core_file in sorted((explicit_root / "core-crash").iterdir()):
                    core_metadata = core_file.lstat()
                    self.assertTrue(stat.S_ISREG(core_metadata.st_mode))
                    self.assertEqual(core_metadata.st_nlink, 1)
                    self.assertLessEqual(core_metadata.st_size, 1)
                    actual_core_files.append(
                        {"name": core_file.name, "size": core_metadata.st_size}
                    )
                self.assertEqual(actual_core_files, result["core_files"])
                self.assertEqual(result["devzero_errno"], errno.EACCES)
                self.assertEqual(result["rw_hint_set_errno"], errno.EACCES)
                assert rw_hint_baseline is not None
                self.assertEqual(result["rw_hint_before"], rw_hint_baseline.hex())
                self.assertEqual(result["sysv_lookup_errno"], errno.ENOENT)
                self.assertIs(result["sysv_private_created"], True)
                self.assertIs(result["mqueue_created"], True)
                self.assertIs(result["mqueue_visible"], True)
                self.assertEqual(result["subprocess"], "subprocess-ok\n")
                self.assertIs(result["devnull_subprocess"], True)
                self.assertEqual(result["devnull_mount"]["mountpoint"], "/dev/null")
                self.assertIn("ro", result["devnull_mount"]["options"])
                self.assertNotIn("nodev", result["devnull_mount"]["options"])
                self.assertEqual(
                    result["devnull_device"],
                    {
                        "gid": 0,
                        "major": 1,
                        "minor": 3,
                        "mode": 0o666,
                        "uid": 0,
                    },
                )
                self.assertEqual(
                    set(result["entrypoint_usage"]),
                    {
                        "waited_delivery_bridge.py",
                        "waited_delivery_hook_adapter.py",
                    },
                )
                for name, usage in result["entrypoint_usage"].items():
                    self.assertTrue(usage.startswith(f"usage: {name} "))
                self.assertGreater(result["zstd"]["compressed_size"], 0)
                self.assertEqual(result["zstd"]["payload_size"], 896)
                self.assertEqual(
                    result["allowed_writes"],
                    {
                        "explicit": "explicit\n",
                        "runtime": "runtime\n",
                        "workspace": "workspace\n",
                    },
                )
                self.assertEqual(result["git"]["status"], "")
                self.assertEqual(result["git"]["tree"], "tracked.txt\n")
                self.assertEqual(result["git"]["blob"], "tracked\n")
                self.assertRegex(result["git"]["head"], r"\A[0-9a-f]{40}\Z")
                self.assertGreater(result["git"]["archive_size"], 0)
                self.assertEqual(
                    result["dev_shm_mount"]["mountpoint"], "/dev/shm"
                )
                self.assertEqual(result["dev_shm_mount"]["filesystem"], "tmpfs")
                self.assertEqual(
                    result["dev_shm_mount"]["source"], "required-ci-private"
                )
                self.assertIn("rw", result["dev_shm_mount"]["options"])
                expected_sysctls = {
                    "/proc/sys/kernel/shmmax": "8388608",
                    "/proc/sys/kernel/shmall": str(
                        8388608 // os.sysconf("SC_PAGE_SIZE")
                    ),
                    "/proc/sys/kernel/shmmni": "64",
                    "/proc/sys/kernel/msgmax": "8192",
                    "/proc/sys/kernel/msgmnb": "65536",
                    "/proc/sys/kernel/msgmni": "64",
                    "/proc/sys/kernel/sem": "64 256 32 64",
                    "/proc/sys/fs/mqueue/queues_max": "64",
                    "/proc/sys/fs/mqueue/msg_max": "64",
                    "/proc/sys/fs/mqueue/msgsize_max": "8192",
                    "/proc/sys/fs/mqueue/msg_default": "16",
                    "/proc/sys/fs/mqueue/msgsize_default": "8192",
                }
                self.assertEqual(result["sysctls"], expected_sysctls)
                self.assertEqual(
                    result["private_markers"],
                    {
                        str(marker): "private\n"
                        for marker in surface_markers.values()
                    },
                )
                assert explicit_marker is not None
                self.assertEqual(
                    explicit_marker.read_text(encoding="utf-8"), "explicit\n"
                )
                for marker in surface_markers.values():
                    self.assertFalse(marker.exists())
                self.assertFalse(host_mqueue_path.exists())
                ctypes.set_errno(0)
                self.assertEqual(libc.shmget(sysv_key, 0, 0), host_shmid)
                assert rw_hint_descriptor is not None
                self.assertEqual(
                    fcntl.fcntl(rw_hint_descriptor, 1035, bytes(8)),
                    rw_hint_baseline,
                )
        finally:
            cleanup_errors: list[str] = []
            if (
                listener_process is not None
                and listener_identity is not None
                and (
                    listener_process.poll() is None
                    or _CANDIDATE_SUPPORT._process_identity(
                        Path("/proc") / str(listener_process.pid)
                    )
                    == listener_identity
                )
            ):
                try:
                    stop_host_ipc_helper(
                        listener_process,
                        listener_identity,
                        expect_graceful=True,
                    )
                except BaseException as error:
                    cleanup_errors.append(str(error))
            listener_terminal = (
                listener_process is None
                or (
                    listener_process.poll() is not None
                    and (
                        listener_identity is None
                        or _CANDIDATE_SUPPORT._process_identity(
                            Path("/proc") / str(listener_process.pid)
                        )
                        != listener_identity
                    )
                )
            )
            if not listener_terminal:
                cleanup_errors.append(
                    "host IPC listener remained active during exact cleanup"
                )
            else:
                for path, expected_kind in (
                    (socket_path, stat.S_ISSOCK),
                    (fifo_path, stat.S_ISFIFO),
                ):
                    try:
                        remove_host_ipc_node(
                            path,
                            listener_nodes.get(path),
                            expected_kind,
                        )
                    except BaseException as error:
                        cleanup_errors.append(str(error))
            if rw_hint_descriptor is not None:
                try:
                    os.close(rw_hint_descriptor)
                except OSError as error:
                    cleanup_errors.append(str(error))
                rw_hint_descriptor = None
            try:
                metadata = rw_hint_path.lstat()
                if rw_hint_identity is not None and (
                    metadata.st_dev,
                    metadata.st_ino,
                ) != rw_hint_identity:
                    raise AssertionError("host fcntl sentinel identity changed")
                if (
                    not stat.S_ISREG(metadata.st_mode)
                    or metadata.st_uid != os.getuid()
                    or metadata.st_nlink != 1
                    or stat.S_IMODE(metadata.st_mode) != 0o444
                ):
                    raise AssertionError(
                        "host fcntl sentinel ownership/type changed"
                    )
                rw_hint_path.unlink()
            except FileNotFoundError:
                if rw_hint_identity is not None:
                    cleanup_errors.append("host fcntl sentinel disappeared")
            except BaseException as error:
                cleanup_errors.append(str(error))
            for root in surface_roots:
                try:
                    metadata = root.lstat()
                    if (metadata.st_dev, metadata.st_ino) != surface_identities[root]:
                        raise AssertionError(
                            f"host private-surface scaffold identity changed: {root}"
                        )
                    marker = surface_markers[root]
                    try:
                        marker_metadata = marker.lstat()
                    except FileNotFoundError:
                        pass
                    else:
                        if (
                            not stat.S_ISREG(marker_metadata.st_mode)
                            or marker_metadata.st_nlink != 1
                        ):
                            raise AssertionError(
                                f"unsafe host private-surface residue: {marker}"
                            )
                        marker.unlink()
                    root.rmdir()
                except BaseException as error:
                    cleanup_errors.append(str(error))
            if listener_terminal:
                try:
                    revalidate_ipc_root()
                    if tuple(ipc_root.iterdir()):
                        raise AssertionError(
                            "host IPC scaffold is not empty before registered cleanup"
                        )
                except BaseException as error:
                    cleanup_errors.append(str(error))
            ctypes.set_errno(0)
            mqueue_cleanup = libc.mq_unlink(mqueue_name.encode("ascii"))
            if mqueue_cleanup != 0 and ctypes.get_errno() != errno.ENOENT:
                cleanup_errors.append(
                    f"POSIX mqueue cleanup failed: errno {ctypes.get_errno()}"
                )
            if host_shmid >= 0:
                ctypes.set_errno(0)
                if libc.shmctl(host_shmid, 0, None) != 0:
                    cleanup_errors.append(
                        f"SysV sentinel cleanup failed: errno {ctypes.get_errno()}"
                    )
                else:
                    ctypes.set_errno(0)
                    if (
                        libc.shmget(sysv_key, 0, 0) != -1
                        or ctypes.get_errno() != errno.ENOENT
                    ):
                        cleanup_errors.append(
                            "SysV sentinel remained after exact cleanup"
                        )
            try:
                ipc_root_cleanup.close()
            except BaseException as error:
                cleanup_errors.append(str(error))
            _finish_strict_live_cleanup(cleanup_errors, core_pattern_bytes)

