                f"    trusted.write_text(\"from pathlib import Path\\nPath({str(canary)!r}).write_text('executed', encoding='utf-8')\\n\", encoding='utf-8')\n"
                "    runpy.run_path(str(trusted), run_name='_required_ci_aba')\n"
